#[test]
#[cfg(not(feature = "extended"))]
fn compiled_product_domain_gate_rejects_extended_surface_centrally() {
    let request = Request::ListScheduledJobs { owner: None };
    let error = require_compiled_product_domain(&request)
        .expect_err("scheduler RPC must be unavailable without the extended profile");
    assert_eq!(error.code, ErrorCode::BadRequest);
    assert!(
        error
            .message
            .contains("opt-in extended local capability profile")
    );

    require_compiled_product_domain(&Request::DaemonStatus)
        .expect("base-profile RPC must remain available");
}

fn mcp_patch<T: serde::Serialize>(config: &T) -> cockpit_proto::SensitiveWirePayload {
    let value = serde_json::to_value(config).unwrap();
    let operations = value
        .get("servers")
        .and_then(serde_json::Value::as_object)
        .into_iter()
        .flatten()
        .map(
            |(name, server)| cockpit_proto::McpConfigPatchOperation::AddServer {
                name: name.clone(),
                server_json: serde_json::to_string(server).unwrap().into(),
            },
        )
        .collect();
    serde_json::to_string(&cockpit_proto::McpConfigPatch { operations })
        .unwrap()
        .into()
}

#[test]
fn mcp_publication_is_a_raw_target_layer_patch() {
    let source = include_str!("dispatch.rs");
    let save = source
        .split("async fn save_mcp_config(")
        .last()
        .expect("MCP save owner")
        .split("async fn publish_mcp_journal_generation(")
        .next()
        .expect("MCP save body");
    for required in [
        "McpConfigPatchOperation::AddServer",
        "McpConfigPatchOperation::MaterializeInheritedServer",
        "McpConfigPatchOperation::UpdateAuthoredServer",
        "McpConfigPatchOperation::DeleteAuthoredServer",
        "raw_document",
        "patch_intent_json",
        "mcp_target_layer_revision(&path)",
    ] {
        assert!(
            save.contains(required),
            "MCP raw-layer owner lost {required}"
        );
    }
    assert!(!save.contains("config.write_private(&path)"));
    let snapshot = source
        .split("fn redacted_mcp_config_snapshot")
        .nth(1)
        .expect("MCP snapshot owner")
        .split("fn canonical_mcp_target_path")
        .next()
        .expect("MCP snapshot body");
    assert!(snapshot.contains("effective_config_json"));
    assert!(snapshot.contains("authored_config_json"));
}

#[test]
fn inherited_mcp_materialization_detects_legacy_literal_credentials() {
    for raw in [
        r#"{"servers":{"legacy":{"transport":"streamable","endpoint":"https://example.test","auth":{"kind":"header","value":"Bearer legacy"}}}}"#,
        r#"{"servers":{"legacy":{"transport":"stdio","command":"legacy","env":{"TOKEN":"legacy"}}}}"#,
        r#"{"servers":{"legacy":{"transport":"stdio","command":"legacy","auth":{"kind":"env","vars":{"TOKEN":"legacy"}}}}}"#,
    ] {
        let config = crate::mcp::config::McpConfig::parse(raw).unwrap();
        assert!(crate::mcp::config::server_has_credential_material(
            &config.servers["legacy"]
        ));
    }
}

#[test]
fn client_teardown_quiesces_dispatch_before_capability_cancellation() {
    let source = include_str!("mod.rs");
    let socket = source
        .split("async fn handle_client_transport_as")
        .nth(1)
        .expect("socket transport")
        .split("async fn select_client_task")
        .next()
        .expect("socket teardown body");
    let abort = socket
        .find("executor_task.abort()")
        .expect("executor abort");
    let join = socket[abort..]
        .find("executor_task).await")
        .map(|offset| abort + offset)
        .expect("executor join");
    let cancel = socket
        .find(".cancel_for_session(client_instance_id)")
        .expect("socket capability cancellation");
    assert!(abort < join && join < cancel);

    let in_process = source
        .split("async fn run_in_process_client")
        .nth(1)
        .expect("in-process transport")
        .split("struct PendingEventLag")
        .next()
        .expect("in-process teardown body");
    let abort_all = in_process
        .find("concurrent_tasks.abort_all()")
        .expect("request abort");
    let join_all = in_process[abort_all..]
        .find("concurrent_tasks.join_next().await")
        .map(|offset| abort_all + offset)
        .expect("request join");
    let attachments = in_process
        .find("drain_client_attachment_ownership")
        .expect("attachment drain");
    let cancel = in_process
        .find(".cancel_for_session(client_instance_id)")
        .expect("in-process capability cancellation");
    assert!(abort_all < join_all && join_all < attachments && attachments < cancel);
}

#[test]
fn oversized_response_is_replaced_before_the_ndjson_writer() {
    let id = Uuid::new_v4();
    let envelope = bounded_response_envelope(
        id,
        Response::PolicyExported {
            bundle_json: "x".repeat(proto::MAX_SERIALIZED_RESPONSE_BYTES),
        },
    );
    assert!(matches!(&envelope.body, proto::Body::Error { .. }));
    assert!(serde_json::to_vec(&envelope).unwrap().len() < proto::MAX_SERIALIZED_RESPONSE_BYTES);
}

