#[tokio::test]
#[cfg(feature = "remote")]
async fn non_owner_rejected() {
    // AC4: every sealed-owner RPC fails closed with an Authorization error for a
    // remote (non-owner) principal, before any handler logic runs.
    let ctx = test_ctx();
    let mut state = remote_state_with_grants(Vec::new());
    for request in sealed_owner_channel_requests() {
        let tag = request.wire_tag();
        let error = handle_request(request, &mut state, &ctx).await.unwrap_err();
        assert_eq!(
            error.code,
            ErrorCode::Authorization,
            "{tag} must reject a non-owner"
        );
    }
}

#[tokio::test]
#[cfg(feature = "remote")]
async fn sealed_owner_rpcs_are_owner_remoted_and_never_leak() {
    // AC3: an authenticated owner request TRAVERSES dispatch (it is NOT rejected
    // at authorization). The value-channel arms (begin/apply/cancel/inventory)
    // are now wired to the durable directory + capability table: for these fixed
    // inputs they return either a content-free client error (an unknown record,
    // a malformed capability id) or a safe success (an empty inventory). The
    // still-deferred action-channel + description-edit arms fail closed with a
    // content-free Internal error. Across ALL of them: never an Authorization
    // error once past the owner gate, and never a leaked apply literal.
    let ctx = test_ctx();
    for request in sealed_owner_channel_requests() {
        let tag = request.wire_tag();
        let mut state = owner_state();
        match handle_request(request, &mut state, &ctx).await {
            Ok(response) => {
                let rendered = serde_json::to_string(&response).unwrap();
                assert!(
                    !rendered.contains("s3cr3t"),
                    "{tag} response must not carry the apply literal"
                );
            }
            Err(error) => {
                assert_ne!(
                    error.code,
                    ErrorCode::Authorization,
                    "{tag} owner request must traverse dispatch, not be authorization-rejected"
                );
                assert!(
                    !error.message.contains("s3cr3t"),
                    "{tag} error must not leak the apply literal"
                );
            }
        }
    }
}

#[tokio::test]
async fn action_admin_unknown_ids_reject_before_persist() {
    // The retired catalog selector is rejected before touching persistence. The
    // owner-declared request is now the only create surface, and its declaration
    // is parsed before a durable action can be minted.
    let ctx = test_ctx();

    let unknown_cases = [
        ("bogus.kind", "0", "none"),
        ("https.notify", "99", "none"), // origin index out of range
        ("https.notify", "0", "bogus_projection"),
    ];
    for (kind_id, origin_id, projection_id) in unknown_cases {
        let mut state = owner_state();
        let error = handle_request(
            Request::CreateSealedAction {
                kind_id: kind_id.into(),
                project_id: "proj".into(),
                description: "notify".into(),
                origin_id: origin_id.into(),
                projection_id: projection_id.into(),
            },
            &mut state,
            &ctx,
        )
        .await
        .unwrap_err();
        assert_eq!(
            error.code,
            ErrorCode::BadRequest,
            "unknown ids ({kind_id}/{origin_id}/{projection_id}) must reject before persist"
        );
    }

    // Positive control: an owner-declared fixed sink persists a daemon-minted
    // action instance.
    let mut state = owner_state();
    let response = handle_request(
        Request::CreateDeclaredSealedAction {
            project_id: "proj".into(),
            description: "notify".into(),
            declaration: proto::SealedActionDeclaration::CommandArgument {
                argv: vec!["notify".into(), "{{sealed_value}}".into()],
            },
        },
        &mut state,
        &ctx,
    )
    .await
    .unwrap();
    match response {
        Response::SealedActionCreated {
            action_id,
            revision,
        } => {
            assert_eq!(revision, 1);
            uuid::Uuid::parse_str(&action_id).expect("action id is a daemon-minted uuid");
        }
        other => panic!("expected SealedActionCreated, got {other:?}"),
    }
}

