/// Like [`stub_config_source`], but with a per-workspace provider layer
/// (`<cwd>/.cockpit/config.json`) as the write target and watch path.
/// `GetProviderCatalogSnapshot` can then mint a genuine provider/MCP edit
/// capability, so save tests exercise the production capability flow instead
/// of fabricating registry entries.
fn stub_layered_config_source() -> crate::daemon::config_source::ConfigSource {
    let providers = stub_providers_config();
    let extended = crate::config::extended::ExtendedConfig::default();
    crate::daemon::config_source::ConfigSource::new(
        move |_cwd| Ok((providers.clone(), extended.clone())),
        |cwd, _provider_id| Some(cwd.join(".cockpit/config.json")),
        |cwd| {
            crate::daemon::config_source::ConfigWatchPaths::new(
                vec![cwd.join(".cockpit/config.json")],
                Vec::new(),
            )
        },
    )
}

pub(crate) fn test_ctx() -> Arc<DaemonContext> {
    test_ctx_with_config_source(stub_config_source())
}

fn disk_test_ctx(db_path: &Path, spool_path: &Path) -> Arc<DaemonContext> {
    let db = Db::open(db_path).expect("file-backed test db");
    let locks = Arc::new(LockManager::in_memory(db.clone()));
    let mut context = DaemonContext::new(
        db.clone(),
        locks,
        DaemonPaths {
            socket: db_path.with_extension("sock"),
            pid_file: db_path.with_extension("pid"),
            ephemeral: false,
        },
        crate::daemon::terminal::test_host_factory(),
        stub_config_source(),
    );
    context.external_journal = Some(Arc::new(
        crate::external_journal::ExternalJournal::for_test_at(db, spool_path),
    ));
    Arc::new(context)
}

/// Generate a unique `DaemonPaths` under a fresh temp directory so parallel
/// nextest processes never share a socket or pid file.  The temp directory is
/// intentionally leaked (`into_path`) — it lives for the context's lifetime
/// and is cleaned by the OS.
fn unique_test_paths(ephemeral: bool) -> DaemonPaths {
    let dir = tempfile::tempdir().expect("temp dir").into_path();
    DaemonPaths {
        socket: dir.join("cockpit.sock"),
        pid_file: dir.join("cockpit.pid"),
        ephemeral,
    }
}

fn test_ctx_with_config_source(
    config_source: crate::daemon::config_source::ConfigSource,
) -> Arc<DaemonContext> {
    let db = Db::open_in_memory().expect("in-memory db");
    let locks = Arc::new(LockManager::in_memory(db.clone()));
    let paths = unique_test_paths(true);
    let ctx = DaemonContext::new(
        db,
        locks,
        paths,
        crate::daemon::terminal::test_host_factory(),
        config_source,
    );
    let generation = ctx.host_capabilities.begin_refresh();
    let mut snapshot = crate::daemon::session_worker::sandbox_capability_snapshot(
        cockpit_proto::FeatureCapabilityState::Available,
        cockpit_proto::FeatureCapabilityState::Available,
    );
    snapshot.generation = generation;
    ctx.host_capabilities.publish(snapshot);
    Arc::new(ctx)
}

/// Keep daemon-owned agent files and the socket/pid spelling below the test's
/// temporary state root.  Session-setup tests intentionally exercise the
/// production service constructor, which derives its owned `agents/` root
/// from the pid-file parent.
fn isolated_test_ctx_with_config_source(
    state_root: &Path,
    config_source: crate::daemon::config_source::ConfigSource,
) -> Arc<DaemonContext> {
    let db = Db::open_in_memory().expect("in-memory db");
    let locks = Arc::new(LockManager::in_memory(db.clone()));
    let paths = DaemonPaths {
        socket: state_root.join("cockpit.sock"),
        pid_file: state_root.join("cockpit.pid"),
        ephemeral: true,
    };
    let ctx = DaemonContext::new(
        db,
        locks,
        paths,
        crate::daemon::terminal::test_host_factory(),
        config_source,
    );
    let generation = ctx.host_capabilities.begin_refresh();
    let mut snapshot = crate::daemon::session_worker::sandbox_capability_snapshot(
        cockpit_proto::FeatureCapabilityState::Available,
        cockpit_proto::FeatureCapabilityState::Available,
    );
    snapshot.generation = generation;
    ctx.host_capabilities.publish(snapshot);
    Arc::new(ctx)
}

