async fn auto_title_model_server(content: Option<String>) -> String {
    use tokio::{
        io::{AsyncReadExt, AsyncWriteExt},
        net::TcpListener,
    };

    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        while let Ok((mut stream, _)) = listener.accept().await {
            let mut buf = Vec::new();
            let mut tmp = [0u8; 4096];
            loop {
                let n = match stream.read(&mut tmp).await {
                    Ok(0) | Err(_) => break,
                    Ok(n) => n,
                };
                buf.extend_from_slice(&tmp[..n]);
                let s = String::from_utf8_lossy(&buf);
                if let Some(idx) = s.find("\r\n\r\n") {
                    let header = &s[..idx];
                    let content_len = header
                        .lines()
                        .find_map(|line| {
                            let line = line.to_ascii_lowercase();
                            line.strip_prefix("content-length:")
                                .map(|value| value.trim().parse::<usize>().unwrap_or(0))
                        })
                        .unwrap_or(0);
                    if buf.len() >= idx + 4 + content_len {
                        break;
                    }
                }
            }
            let Some(content) = &content else {
                let resp = "HTTP/1.1 500 Internal Server Error\r\n\
                                Content-Length: 0\r\nConnection: close\r\n\r\n";
                let _ = stream.write_all(resp.as_bytes()).await;
                continue;
            };
            let escaped = content
                .replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('\n', "\\n")
                .replace('\r', "\\r");
            let payload = format!(
                "{{\"id\":\"c\",\"object\":\"chat.completion\",\"created\":0,\
                     \"model\":\"m\",\"system_fingerprint\":null,\
                     \"choices\":[{{\"index\":0,\"message\":{{\"role\":\"assistant\",\
                     \"content\":[{{\"type\":\"text\",\"text\":\"{escaped}\"}}]}},\
                     \"logprobs\":null,\"finish_reason\":\"stop\"}}],\
                     \"usage\":{{\"prompt_tokens\":1,\"total_tokens\":2,\
                     \"prompt_tokens_details\":{{\"cached_tokens\":0}}}}}}"
            );
            let resp = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\
                     Content-Length: {}\r\nConnection: close\r\n\r\n{}",
                payload.len(),
                payload
            );
            let _ = stream.write_all(resp.as_bytes()).await;
            let _ = stream.flush().await;
        }
    });
    format!("http://{addr}/v1")
}

async fn auto_title_error_model_server(
    body_sentinel: &'static str,
    request_id: &'static str,
) -> String {
    use tokio::{
        io::{AsyncReadExt, AsyncWriteExt},
        net::TcpListener,
    };

    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        while let Ok((mut stream, _)) = listener.accept().await {
            let mut request = [0u8; 4096];
            let _ = stream.read(&mut request).await;
            let body = format!("{{\"error\":\"{body_sentinel}\"}}");
            let response = format!(
                "HTTP/1.1 429 Too Many Requests\r\nContent-Type: application/json\r\n\
                 x-request-id: {request_id}\r\nContent-Length: {}\r\n\
                 Connection: close\r\n\r\n{body}",
                body.len()
            );
            let _ = stream.write_all(response.as_bytes()).await;
            let _ = stream.flush().await;
        }
    });
    format!("http://{addr}/v1")
}

fn write_curator_skill(skill_root: &Path, name: &str) {
    let dir = skill_root.join(name);
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("SKILL.md"),
        format!("---\nname: {name}\ndescription: test skill\n---\n\nUse it.\n"),
    )
    .unwrap();
    std::fs::write(
        dir.join(".cockpit-provenance.json"),
        r#"{
  "created_origin": "background_review",
  "writes": [{"action":"create","origin":"background_review","unix_seconds":1}],
  "pinned": false
}"#,
    )
    .unwrap();
}

