#[derive(Debug, Clone, PartialEq, Eq)]
enum AuthzExpectation {
    Allow(AuthzAllowedOutcome),
    #[cfg(feature = "remote")]
    Deny(ErrorCode),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum AuthzAllowedOutcome {
    Response,
    Error(ErrorCode),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AuthzLevel {
    Owner,
    #[cfg(feature = "remote")]
    Writer,
    #[cfg(feature = "remote")]
    Readonly,
    #[cfg(feature = "remote")]
    NoAccess,
}

impl AuthzLevel {
    #[cfg(feature = "remote")]
    const ALL: [Self; 4] = [Self::Owner, Self::Writer, Self::Readonly, Self::NoAccess];

    fn label(self) -> &'static str {
        match self {
            Self::Owner => "owner",
            #[cfg(feature = "remote")]
            Self::Writer => "writer",
            #[cfg(feature = "remote")]
            Self::Readonly => "readonly",
            #[cfg(feature = "remote")]
            Self::NoAccess => "no_access",
        }
    }

    /// Whether this level can attach to a session at all. Local builds only
    /// have `Owner`, so the answer is unconditionally yes there.
    fn can_attach(self) -> bool {
        #[cfg(feature = "remote")]
        {
            self != Self::NoAccess
        }
        #[cfg(not(feature = "remote"))]
        {
            true
        }
    }

    /// Whether this level holds write-capable session access. Local builds
    /// only have `Owner`, so the answer is unconditionally yes there.
    fn can_write(self) -> bool {
        #[cfg(feature = "remote")]
        {
            matches!(self, Self::Owner | Self::Writer)
        }
        #[cfg(not(feature = "remote"))]
        {
            true
        }
    }
}

#[derive(Debug, Clone)]
struct AuthzDispatchCase {
    kind: &'static str,
    owner: AuthzExpectation,
    #[cfg(feature = "remote")]
    writer: AuthzExpectation,
    #[cfg(feature = "remote")]
    readonly: AuthzExpectation,
    #[cfg(feature = "remote")]
    no_access: AuthzExpectation,
    #[cfg(feature = "remote")]
    known_holes: &'static [AuthzKnownHole],
}

#[cfg(feature = "remote")]
#[derive(Debug, Clone)]
struct AuthzKnownHole {
    marker: &'static str,
    level: AuthzLevel,
    expected: ErrorCode,
    actual: AuthzAllowedOutcome,
}

impl AuthzDispatchCase {
    fn expectation(&self, level: AuthzLevel) -> AuthzExpectation {
        match level {
            AuthzLevel::Owner => self.owner.clone(),
            #[cfg(feature = "remote")]
            AuthzLevel::Writer => self.writer.clone(),
            #[cfg(feature = "remote")]
            AuthzLevel::Readonly => self.readonly.clone(),
            #[cfg(feature = "remote")]
            AuthzLevel::NoAccess => self.no_access.clone(),
        }
    }
}

fn authz_owner_only(kind: &'static str) -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind,
        owner: authz_allow(kind),
        #[cfg(feature = "remote")]
        writer: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        readonly: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        no_access: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        known_holes: &[],
    }
}

#[cfg(feature = "remote")]
fn authz_session_writer(kind: &'static str) -> AuthzDispatchCase {
    authz_session_writer_with_known_holes(kind, &[])
}

#[cfg(not(feature = "remote"))]
fn authz_session_writer(kind: &'static str) -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind,
        owner: authz_allow(kind),
    }
}

/// Bulk message bytes are bound to an authenticated remote operation, rather
/// than merely the remote principal used by this legacy socket authz matrix.
/// The owner fixture reaches the non-oracular unknown-transfer result; the
/// remote-writer fixture intentionally proves that an actorless transport
/// cannot obtain an opaque-transfer owner even after its session-writer grant
/// passed the central authorization gate.
fn authz_bulk_user_message() -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind: "send_user_message_bulk",
        owner: AuthzExpectation::Allow(AuthzAllowedOutcome::Error(ErrorCode::BadRequest)),
        #[cfg(feature = "remote")]
        writer: AuthzExpectation::Allow(AuthzAllowedOutcome::Error(ErrorCode::Authorization)),
        #[cfg(feature = "remote")]
        readonly: AuthzExpectation::Deny(ErrorCode::ReadOnly),
        #[cfg(feature = "remote")]
        no_access: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        known_holes: &[],
    }
}

/// The authorization matrix must reach the attached-session writer gate for a
/// bulk chunk, but it must not stage a valid transfer: the matrix owns no
/// transfer cleanup and a successful write can leave the socket teardown
/// waiting on that durable path.  An invalid base64 body is rejected only
/// after authorization, so it proves the same boundary without entering the
/// bulk writer.
fn authz_bulk_transfer_chunk() -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind: "write_bulk_transfer_chunk",
        owner: AuthzExpectation::Allow(AuthzAllowedOutcome::Error(ErrorCode::BadRequest)),
        #[cfg(feature = "remote")]
        writer: AuthzExpectation::Allow(AuthzAllowedOutcome::Error(ErrorCode::BadRequest)),
        #[cfg(feature = "remote")]
        readonly: AuthzExpectation::Deny(ErrorCode::ReadOnly),
        #[cfg(feature = "remote")]
        no_access: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        known_holes: &[],
    }
}

#[cfg(feature = "remote")]
fn authz_session_writer_with_known_holes(
    kind: &'static str,
    known_holes: &'static [AuthzKnownHole],
) -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind,
        owner: authz_allow(kind),
        writer: authz_allow(kind),
        readonly: AuthzExpectation::Deny(ErrorCode::ReadOnly),
        no_access: AuthzExpectation::Deny(ErrorCode::Authorization),
        known_holes,
    }
}

fn authz_session_reader(kind: &'static str) -> AuthzDispatchCase {
    AuthzDispatchCase {
        kind,
        owner: authz_allow(kind),
        #[cfg(feature = "remote")]
        writer: authz_allow(kind),
        #[cfg(feature = "remote")]
        readonly: authz_allow(kind),
        #[cfg(feature = "remote")]
        no_access: AuthzExpectation::Deny(ErrorCode::Authorization),
        #[cfg(feature = "remote")]
        known_holes: &[],
    }
}

