fn authz_allow(kind: &'static str) -> AuthzExpectation {
    AuthzExpectation::Allow(authz_allowed_outcome(kind))
}

fn authz_allowed_outcome(kind: &str) -> AuthzAllowedOutcome {
    match kind {
        "attach"
        | "attach_knowledge_base_session"
        | "detach_knowledge_base_session"
        | "subagent_transcript"
        | "cancel_attachment_upload"
        | "goal_status"
        | "clear_goal"
        | "list_assistants"
        | "cancel_provider_oauth"
        | "export_session_data"
        | "write_bulk_transfer_chunk"
        | "curator"
        | "resume_paused_work"
        | "cancel_paused_work"
        | "fs_list"
        | "fs_write"
        | "fs_create_dir"
        | "read_session_messages"
        | "read_assistant_inbox"
        | "read_client_submission_receipt"
        | "read_history_page"
        | "read_subagent_history_page"
        | "unarchive_session"
        | "fork_session"
        | "btw_create"
        | "btw_end"
        | "rename_session"
        | "share_session"
        | "record_session_note"
        | "resource_snapshot"
        | "promote_resource"
        | "set_approval_mode"
        | "set_sandbox"
        | "set_sandbox_escalation"
        | "set_caffeinate"
        | "refresh_env"
        | "record_usage"
        | "get_usage_counts"
        | "stats_rollup"
        | "create_goal"
        | "get_workspace_trust"
        | "get_startup_disclosures"
        | "get_app_flag"
        | "mark_app_flag_seen"
        | "set_workspace_trust"
        | "guidance_estimate"
        | "list_guidance_proposals"
        | "clean_managed_workspace_lease"
        | "restart_if_idle"
        | "stop_daemon"
        | "refresh_host_capabilities" => AuthzAllowedOutcome::Response,
        "count_pinned_messages"
        | "list_pinned_message_seqs"
        | "list_pinned_messages_with_text"
        | "pinned_message_state"
        | "pin_message"
        | "unpin_message"
        | "toggle_pinned_message"
        | "list_project_notes"
        | "create_project_note" => AuthzAllowedOutcome::Response,
        // v10-only owner-remoted sealed-owner channel. The matrix daemon has
        // an empty but available SQLite store, so natural empty/read and
        // idempotent paths return their typed responses; generated missing
        // record/action IDs produce BadRequest after authz. These cases must
        // not be mistaken for unavailable-persistence Internal sentinels.
        "review_guidance_proposal" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "begin_sealed_owner_operation" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "apply_sealed_owner_operation" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        "cancel_sealed_owner_operation" => AuthzAllowedOutcome::Response,
        "sealed_owner_inventory"
        | "list_sealed_actions"
        | "create_sealed_action"
        | "create_declared_sealed_action"
        | "retire_sealed_action" => AuthzAllowedOutcome::Response,
        "edit_sealed_owner_description"
        | "revise_sealed_action_description"
        | "revise_sealed_action_enabled" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "begin_attachment_upload"
        | "upload_attachment_chunk"
        | "finish_attachment_upload"
        | "fs_stat"
        | "fs_read"
        | "fs_rename"
        | "fs_delete"
        | "git_status"
        | "git_diff_file"
        | "git_diff"
        | "attach_terminal"
        | "create_scheduled_job"
        | "list_scheduled_jobs"
        | "delete_scheduled_job"
        | "set_scheduled_job_enabled"
        | "run_scheduled_job"
        | "auto_title"
        | "create_assistant_session"
        | "resolve_assistant_session"
        | "store_flycockpit_credential"
        | "clear_flycockpit_credential"
        | "set_goal_status"
        | "import_session_archive"
        | "put_named_secret"
        | "delete_named_secret"
        | "put_provider_credential"
        | "delete_provider_credential"
        | "put_subscription_ack"
        | "begin_provider_oauth"
        | "complete_provider_oauth"
        | "begin_mcp_oauth"
        | "complete_mcp_oauth"
        | "upsert_provider_config"
        | "save_provider_config"
        | "delete_provider_config"
        | "set_provider_layer_metadata"
        // An unstaged transfer reference is a bad request, not an authz failure.
        // The redacted-export reader rejects an unknown/wrong-kind transfer id
        // the same way (no bytes) — a BadRequest, once past the owner gate.
        | "read_bulk_transfer_chunk"
        | "read_redacted_export_chunk" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // Both attach first (`authz_kind_needs_attached_state`), so the owner
        // cell exercises the attached handler: `lsp_control` always resolves to
        // an `LspControlResult` message and `get_inventory_bundle` projects the
        // attached session's inventory.
        "lsp_control"
        | "get_inventory_bundle"
        | "get_session_setup_snapshot"
        | "get_guidance_enablement_trace"
        | "read_agent_tree"
        | "read_agent_attention"
        | "git_review_sources"
        | "git_repo_status"
        | "find_worktree_root" => AuthzAllowedOutcome::Response,
        "get_agent_effective_settings" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "terminal_ingress_begin"
        | "terminal_ingress_chunk"
        | "terminal_ingress_finish"
        | "terminal_ingress_status"
        | "terminal_input"
        | "terminal_resize"
        | "close_terminal" => {
            AuthzAllowedOutcome::Error(ErrorCode::InvalidIngress)
        }
        "set_project_note_content" | "rename_project_note" | "delete_project_note" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        "open_terminal" => AuthzAllowedOutcome::Error(ErrorCode::RootMissing),
        "set_model_favorite" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // Terminal-by-event: the request Acks and the verified/rejected outcome
        // arrives as a correlated DefaultModelUpdateResult.
        "set_default_model" => AuthzAllowedOutcome::Response,
        "send_user_message"
        | "steer_delegation"
        | "remove_queued_user_message"
        | "remove_newest_queued_user_message"
        | "remove_editable_queued_user_messages"
        | "set_queued_user_message_class"
        | "promote_queued_user_messages"
        | "send_now_queued_user_message"
        | "repair_resume"
        | "cancel_turn"
        | "resolve_interrupt"
        | "archive_session"
        | "discard_session"
        | "set_active_model"
        | "set_agent"
        | "set_tool_surface_override"
        | "set_goal_settings_override"
        | "set_delegation_recursion"
        | "set_preflight"
        | "set_longcache"
        | "set_redaction"
        | "set_tandem_models"
        | "refresh_config"
        | "cancel_schedule"
        | "prune"
        | "compact"
        | "resume_from_compaction"
        | "pin" => AuthzAllowedOutcome::Error(ErrorCode::Internal),
        // `recover_security_blocked_media` validates the owner-principal binding
        // first, then short-circuits on the missing storage authority before the
        // attach check, so a detached owner reaches the `Internal` "media storage
        // authority is unavailable" post-auth error.
        "recover_security_blocked_media" | "migrate_kek_placement" => {
            AuthzAllowedOutcome::Error(ErrorCode::Internal)
        }
        // `register_local_path_media` and `retain_https_media` both call
        // `require_attached` before anything else and map the detached state to
        // `media_attachment_unavailable`, so the owner-allowed cell surfaces
        // `BadRequest` (retain additionally maps its missing-storage authority to
        // the same `BadRequest`, never `Internal`).
        "register_local_path_media" | "retain_https_media" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        "admit_image_ingress"
        | "discard_image_ingress_draft"
        | "begin_media_upload"
        | "append_media_upload_chunk"
        | "cancel_media_upload"
        | "finalize_media_upload"
        | "discard_unreferenced_media_attachment"
        | "resolve_agent_decision"
        | "apply_agent_session_override" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        "list_leak_reports" | "list_secret_inventory" | "get_flycockpit_account" => {
            AuthzAllowedOutcome::Response
        }
        // `cancel_mcp_oauth` is an idempotent cancel: its handler always returns
        // `Ok(McpOAuthCancelled { cancelled })` (false for the matrix's unknown
        // flow id), never an error, so the owner-allowed cell is a `Response`.
        "cancel_mcp_oauth" => AuthzAllowedOutcome::Response,
        // The catalog snapshot is a read that must survive a missing provider
        // layer (fresh install): the stub config source has no write target, so
        // the response carries no edit capability, but the owner cell is still
        // a `Response`.
        "get_provider_catalog_snapshot" | "get_provider_usage_snapshot" => {
            AuthzAllowedOutcome::Response
        }
        // `fetch_provider_models` persists refreshed model config, so the
        // ephemeral matrix daemon rejects it with `bad_request` before any
        // fetch, exactly like the sibling provider-config owner mutations.
        "fetch_provider_models" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "apply_provider_mutation" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // These leak commands pass the owner-only gate, then the dispatch handler
        // maps a missing leak record (existence-hiding) to `Authorization`
        // "unauthorized" for the bogus report id used by the matrix request.
        "begin_leak_reveal" | "cancel_leak_reveal" | "mark_leak_rotated" | "delete_leak_report" => {
            AuthzAllowedOutcome::Error(ErrorCode::Authorization)
        }
        // The matrix probe sends a fabricated local operation id; the daemon
        // rejects it with BadRequest after authz.
        "get_local_operation_settlement" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // Owner-remoted settings/policy reads project the effective config; the
        // owner cell resolves to a `Response` like the other read snapshots.
        "export_policy" | "get_image_spend_policy" => AuthzAllowedOutcome::Response,
        // LOCAL owner image-control LIST reads project the (empty, on the
        // ephemeral matrix daemon) registry, so the owner cell is a `Response`.
        "image_endpoint_list" | "image_target_list" | "image_workflow_list" => {
            AuthzAllowedOutcome::Response
        }
        // LOCAL owner image-control GET reads reference an id absent from the
        // ephemeral daemon's empty registry, so the owner-allowed cell surfaces
        // the daemon-layer not-found mapping (`bad_request`) post-auth.
        "image_endpoint_get" | "image_target_get" | "image_workflow_get" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        // LOCAL owner image-control MUTATIONS: the unconditional generation CAS
        // runs first after the owner gate, and the matrix probe fabricates
        // `expected_config_generation: 1` against the fresh daemon's generation
        // 0 — so the owner-allowed cell surfaces `Conflict` before the deeper
        // payload validation. The `ImageGenerationConfig::new` `BadRequest`
        // funnel is covered by the dedicated
        // `image_control_mutation_rejects_malformed_payload_after_generation_cas`
        // test below rather than by this matrix.
        "image_endpoint_create"
        | "image_endpoint_update"
        | "image_endpoint_delete"
        | "image_target_create"
        | "image_target_update"
        | "image_target_delete"
        | "image_target_set_default"
        | "image_workflow_upload"
        | "image_workflow_bind"
        | "image_workflow_delete" => AuthzAllowedOutcome::Error(ErrorCode::Conflict),
        // Owner-remoted settings/setup/flycockpit mutations validate their
        // caller-supplied payload after the owner gate; the matrix request's
        // bogus inputs (or the fresh, untrusted workspace) surface `BadRequest`
        // just like the sibling secret/provider owner mutations above. The
        // ephemeral-daemon owner mutations (`setup_copilot_auth`,
        // `save_mcp_config`, the flycockpit ones) reject via the ephemeral
        // guard; `save_extended_config` rejects the non-`config.json` target;
        // `save_image_spend_policy` rejects the malformed settings JSON.
        "setup_copilot_auth"
        | "save_mcp_config"
        | "save_extended_config"
        | "save_image_spend_policy"
        | "set_flycockpit_connector_enabled"
        | "sync_flycockpit_org_policy"
        | "enroll_flycockpit_org_sync" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // `import_policy` and `apply_setup_wizard` validate their caller-supplied
        // payload inside the owner handler, which maps every parse /
        // unsupported-descriptor failure through `internal` (not `bad_request`),
        // so the owner-allowed cell surfaces `Internal` for the matrix's bogus
        // bundle / wizard id. (Both stay owner-only; only the post-auth error
        // code differs from the sibling `bad_request` mutations above.)
        "import_policy" | "apply_setup_wizard" => AuthzAllowedOutcome::Error(ErrorCode::Internal),
        // v10 `delete_session` rejects an active session with a typed `Conflict`
        // ("end it before deleting") before any deletion. The matrix's
        // cross-session-paused-work scenario keeps the target session active, so
        // the owner-allowed cell surfaces `Conflict` — not the `Internal` shared
        // by the other session-writer mutations above. (v9 envelopes retain the
        // old delete-active behavior; the version gate is exercised by the
        // dedicated `delete_session_rejects_active_session` /
        // `delete_session_v9_envelope_does_not_reject_active_session` tests.)
        "delete_session" => AuthzAllowedOutcome::Error(ErrorCode::Conflict),
        // v10 owner-remoted CLI-surface reads project non-secret state, so the
        // owner cell resolves to a `Response`. `get_session_compactions` reads
        // the seeded matrix session (empty compaction list);
        // `diagnose_media_reservation` uses the valid `session` scope.
        "list_packages"
        | "get_connector_state"
        | "get_org_sync_status"
        | "list_failed_tool_calls"
        | "get_assistant"
        | "get_session_compactions"
        | "diagnose_media_reservation"
        | "get_doctor_snapshot"
        | "get_agent_inventory"
        | "get_extended_config_snapshot" => AuthzAllowedOutcome::Response,
        // Image-sidecar Get is a concurrent handler with its own attach
        // gate (`BadRequest`). Create/Revoke go through serialized
        // `require_attached` (`NotAttached`). The default owner matrix
        // probe is detached, so the owner cell surfaces those attach
        // errors after the owner-only check.
        "get_image_sidecar_authority_snapshot" => {
            AuthzAllowedOutcome::Error(ErrorCode::BadRequest)
        }
        "create_image_sidecar_grant" | "revoke_image_sidecar_grant" => {
            AuthzAllowedOutcome::Error(ErrorCode::NotAttached)
        }
        // Coordinator failures are carried in a typed redacted DTO, so every
        // owner-authorized installation endpoint reaches a response rather
        // than a dispatch-level error.
        "agent_installation_begin"
        | "agent_installation_submit_choice"
        | "agent_installation_list"
        | "agent_installation_inspect" => AuthzAllowedOutcome::Response,
        // Code-root capability probes deliberately use fresh, unknown opaque
        // authorities. The owner reaches the handler, which rejects the
        // forged authority after the central owner gate.
        "attach_existing_code_root_v1"
        | "close_code_root_attachment_v1"
        | "attach_existing_code_root_with_acp_ingress_v1"
        | "close_acp_code_root_attachment_v1"
        | "read_code_root_v1"
        | "read_code_root_deliveries_v1"
        | "ack_code_root_deliveries_v1"
        | "resolve_code_root_interrupt_v1"
        | "execute_storage_cleanup"
        | "set_primary_assistant_soul_edit_mode" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // Root creation requires a configured model; the matrix daemon is
        // intentionally model-less. Discovery and the owner configuration /
        // storage read paths remain fully typed on an empty daemon.
        "create_code_root_v1"
        | "create_code_root_with_acp_ingress_v1" => AuthzAllowedOutcome::Error(ErrorCode::Internal),
        "discover_code_roots_v1"
        | "set_workspace_history_scope"
        | "get_workspace_history_scope"
        | "get_storage_report"
        | "preview_storage_cleanup"
        | "cancel_all_session_work"
        | "exit_guard_status"
        | "release_exit_guard" => AuthzAllowedOutcome::Response,
        // The authz probe intentionally uses an unknown inbox item. Reaching
        // the writer handler must therefore fail after authorization rather
        // than manufacture a durable acknowledgement.
        "acknowledge_assistant_inbox_human_read" => {
            AuthzAllowedOutcome::Error(ErrorCode::Internal)
        }
        "knowledge_dream_status" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        "promote_to_persistent" => AuthzAllowedOutcome::Response,
        "run_knowledge_dream" => AuthzAllowedOutcome::Response,
        // `docs_ask` is authorized for the owner but then resolves workspace
        // trust for its (project_root:None ⇒ daemon canonical cwd) workspace,
        // which the ephemeral matrix daemon never trusts — so it fails closed
        // with `Internal` post-auth, before any docs pipeline / inference runs.
        // The authz boundary (owner-allowed, non-owner-denied) is what this
        // matrix verifies.
        "docs_ask" => AuthzAllowedOutcome::Error(ErrorCode::Internal),
        // v10 owner-remoted persistent mutations (including the reclassified
        // `upsert_assistant`) reject on the ephemeral matrix daemon before any
        // work, exactly like the sibling ephemeral-guarded owner mutations.
        "upsert_assistant"
        | "add_package"
        | "import_package"
        | "prune_packages"
        | "import_kcl_packages"
        | "purge_ended_sessions"
        | "delete_assistant"
        | "repair_media_reservation"
        | "save_assistant_definition"
        | "begin_agent_editor_lease"
        | "complete_agent_editor_lease"
        | "apply_extended_config_patch"
        | "get_agent_edit_snapshot" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // `get_agent_editor_lease_settlement` rejects the probe's non-UUID
        // lease id ("lease") before any registry lookup.
        "get_agent_editor_lease_settlement" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        // `mutate_agent` rejects the probe's fabricated mutation intent hash
        // (`"00" * 32`) before any other validation, so the owner-allowed cell
        // surfaces `BadRequest`.
        "mutate_agent" => AuthzAllowedOutcome::Error(ErrorCode::BadRequest),
        other => panic!("unhandled authz allowed outcome for {other}"),
    }
}

