async fn assert_attachment_mutating_happy(kind: &str) {
    let mut ctx = test_ctx();
    let tmp = tempfile::tempdir().unwrap();
    let media_tmp = tempfile::tempdir().unwrap();
    // The durable attachment finalize path requires provisioned media storage;
    // mirror the `media_upload_production_dispatch_cancel_finalize_and_status`
    // reference so storage is available end-to-end over the socket-backed ctx.
    let db = ctx.db.clone();
    Arc::get_mut(&mut ctx).unwrap().media_storage_recovery = Some(Arc::new(
        crate::media_storage::MediaStorageRecovery::open_or_create(
            db,
            &media_tmp.path().join("media"),
        )
        .unwrap(),
    ));
    let (session_id, _work_rx) = live_worker_with_receiver(&ctx, tmp.path()).await;
    let png = sample_png();
    let sha = sha256_hex(&png);
    let data = base64::engine::general_purpose::STANDARD.encode(&png);
    let (server_stream, client_stream) = test_stream_pair();
    let mut client = ProtoStream::new(client_stream);
    let server = tokio::spawn(handle_client_transport(server_stream, ctx.clone()));
    match recv_body(&mut client).await {
        Body::Response { id, response } => {
            assert_eq!(id, Uuid::nil());
            assert!(matches!(*response, Response::DaemonStatus { .. }));
        }
        other => panic!("expected daemon hello, got {other:?}"),
    }
    let attach_id = Uuid::new_v4();
    client
        .send(&Envelope::request(
            attach_id,
            attach_existing_request(session_id, tmp.path()),
        ))
        .await
        .expect("send attachment attach");
    recv_dispatch_matrix_response(&mut client, attach_id)
        .await
        .expect("attach for attachment upload");
    let begin_id = Uuid::new_v4();
    client
        .send(&Envelope::request(
            begin_id,
            Request::BeginAttachmentUpload {
                mime: proto::IMAGE_ATTACHMENT_MIME_PNG.into(),
                byte_len: png.len() as u64,
                sha256: sha,
                purpose: proto::AttachmentPurpose::UserMessageImage,
            },
        ))
        .await
        .expect("send begin upload");
    let Response::AttachmentUploadStarted { upload_id, .. } =
        recv_dispatch_matrix_response(&mut client, begin_id)
            .await
            .expect("begin upload")
    else {
        panic!("expected AttachmentUploadStarted");
    };

    if kind == "begin_attachment_upload" {
        let chunk_id = Uuid::new_v4();
        client
            .send(&Envelope::request(
                chunk_id,
                Request::UploadAttachmentChunk {
                    upload_id,
                    offset: 0,
                    data_base64: data,
                },
            ))
            .await
            .expect("send chunk");
        assert!(matches!(
            recv_dispatch_matrix_response(&mut client, chunk_id)
                .await
                .expect("chunk after begin"),
            Response::AttachmentChunkAccepted { .. }
        ));
    } else if kind == "cancel_attachment_upload" {
        let cancel_id = Uuid::new_v4();
        client
            .send(&Envelope::request(
                cancel_id,
                Request::CancelAttachmentUpload { upload_id },
            ))
            .await
            .expect("send cancel");
        assert!(matches!(
            recv_dispatch_matrix_response(&mut client, cancel_id)
                .await
                .expect("cancel upload"),
            Response::Ack
        ));
        let finish_id = Uuid::new_v4();
        client
            .send(&Envelope::request(
                finish_id,
                Request::FinishAttachmentUpload { upload_id },
            ))
            .await
            .expect("send finish after cancel");
        let err = recv_dispatch_matrix_response(&mut client, finish_id)
            .await
            .expect_err("cancel removes pending upload");
        assert_eq!(err.code, ErrorCode::BadRequest);
    } else {
        let chunk_id = Uuid::new_v4();
        client
            .send(&Envelope::request(
                chunk_id,
                Request::UploadAttachmentChunk {
                    upload_id,
                    offset: 0,
                    data_base64: data,
                },
            ))
            .await
            .expect("send chunk");
        assert!(matches!(
            recv_dispatch_matrix_response(&mut client, chunk_id)
                .await
                .expect("chunk upload"),
            Response::AttachmentChunkAccepted { .. }
        ));
        let finish_id = Uuid::new_v4();
        client
            .send(&Envelope::request(
                finish_id,
                Request::FinishAttachmentUpload { upload_id },
            ))
            .await
            .expect("send finish");
        assert!(matches!(
            recv_dispatch_matrix_response(&mut client, finish_id)
                .await
                .expect("finish upload"),
            Response::AttachmentUploaded { .. }
        ));
    }
    drop(client);
    server
        .await
        .expect("server task joins")
        .expect("server task succeeds");
}

async fn assert_knowledge_base_session_mutating_happy(kind: &str) {
    let ctx = test_ctx();
    let root = tempfile::tempdir().unwrap();
    let project_root = root.path().to_string_lossy().into_owned();
    let project_id = crate::session::project_id_for(root.path()).unwrap();
    let session = ctx
        .db
        .create_session(&project_id, &project_root, "Build")
        .await
        .unwrap();
    if kind == "detach_knowledge_base_session" {
        ctx.db
            .attach_session_to_knowledge_base("kb", &project_root, session.session_id)
            .await
            .unwrap();
    }
    let request = if kind == "attach_knowledge_base_session" {
        Request::AttachKnowledgeBaseSession {
            knowledge_base_id: "kb".into(),
            session_id: session.session_id,
        }
    } else {
        Request::DetachKnowledgeBaseSession {
            knowledge_base_id: "kb".into(),
            session_id: session.session_id,
        }
    };
    let response = dispatch_matrix_request(&ctx, request)
        .await
        .expect("knowledge-base session attachment mutation");
    assert!(matches!(response, Response::Ack));
    let attached: i64 = ctx
        .db
        .read(move |conn| {
            let count = conn.query_row(
                "SELECT COUNT(*) FROM knowledge_base_session_attachments
                 WHERE kb_id = ?1 AND project_root = ?2 AND session_id = ?3",
                rusqlite::params!["kb", project_root, session.session_id.to_string()],
                |row| row.get(0),
            )?;
            Ok(count)
        })
        .await
        .unwrap();
    assert_eq!(
        attached,
        (kind == "attach_knowledge_base_session") as i64,
        "knowledge-base attachment mutation must durably change its exact row"
    );
}

