fn minimal_import_archive_base64(redacted: bool) -> (Uuid, String) {
    let session_id = Uuid::new_v4();
    let manifest = serde_json::json!({
        "schema": "cockpit-session-export/4",
        "redacted": redacted,
        "target": {
            "project_id": "import-dispatch-test",
            "project_root": "/tmp/import-dispatch-test"
        },
        "sessions": [{
            "session_id": session_id,
            "short_id": "import",
            "parent_session_id": null,
            "fork_point_turn_id": null,
            "active_model": {
                "provider": "test-provider",
                "model": "test-model"
            },
            "session_entry_mode": "code",
            "active_agent": "Build",
            "started_at": 100,
            "ended_at": null,
            "title": "Imported through daemon"
        }]
    });
    let mut cursor = std::io::Cursor::new(Vec::new());
    let mut zip = zip::ZipWriter::new(&mut cursor);
    let options = zip::write::SimpleFileOptions::default();
    zip.start_file("manifest.json", options).unwrap();
    zip.write_all(serde_json::to_string(&manifest).unwrap().as_bytes())
        .unwrap();
    zip.start_file("events.json", options).unwrap();
    zip.write_all(b"[]").unwrap();
    zip.finish().unwrap();
    let encoded = base64::Engine::encode(
        &base64::engine::general_purpose::STANDARD,
        cursor.into_inner(),
    );
    (session_id, encoded)
}

/// Build a bulk transfer reference for `bytes` and stage them, as a peer would
/// via `WriteBulkTransferChunk` before sending `ImportSessionArchive`.
fn stage_archive_transfer(bytes: &[u8]) -> proto::bulk_transfer::BulkTransferRef {
    let reference = archive_transfer_ref(bytes);
    let chunk_size = crate::daemon::bulk_staging::STAGED_CHUNK_BYTES;
    if bytes.is_empty() {
        crate::daemon::bulk_staging::write_chunk(
            &reference,
            0,
            &[],
            &crate::resource_limits::ClientQuotaKey::for_test(1),
        )
        .expect("stage empty archive");
        return reference;
    }
    for (index, chunk) in bytes.chunks(chunk_size).enumerate() {
        crate::daemon::bulk_staging::write_chunk(
            &reference,
            index as u32,
            chunk,
            &crate::resource_limits::ClientQuotaKey::for_test(1),
        )
        .expect("stage chunk");
    }
    reference
}

/// A reference whose bytes were never staged: the daemon must reject it.
fn archive_transfer_ref(bytes: &[u8]) -> proto::bulk_transfer::BulkTransferRef {
    use proto::bulk_transfer::{BulkMimeClass, BulkTransferRef, transfer_id_from_bytes};
    use rand::RngExt as _;
    use sha2::{Digest as _, Sha256};

    let mut hasher = Sha256::new();
    hasher.update(bytes);
    let mut digest = [0u8; 32];
    digest.copy_from_slice(&hasher.finalize());
    let mut id = [0u8; 16];
    rand::rng().fill(&mut id[..]);
    if id.iter().all(|b| *b == 0) {
        id[0] = 1;
    }
    BulkTransferRef::new(
        transfer_id_from_bytes(id).expect("nonzero transfer id"),
        bytes.len() as u64,
        digest,
        BulkMimeClass::Archive,
    )
    .expect("archive transfer reference")
}

/// A staged chunk is retained and acknowledged with its next index.
async fn assert_write_bulk_transfer_chunk_happy() {
    let ctx = test_ctx();
    let body = b"bulk-transfer-chunk-body".to_vec();
    let reference = archive_transfer_ref(&body);
    let response = dispatch_matrix_request(
        &ctx,
        Request::WriteBulkTransferChunk {
            transfer: reference.clone(),
            chunk_index: 0,
            data_base64: base64::engine::general_purpose::STANDARD.encode(&body),
        },
    )
    .await
    .expect("a well-formed chunk is accepted");
    match response {
        Response::BulkTransferChunkAccepted {
            next_chunk_index,
            complete,
            idle_timeout_ms,
            ..
        } => {
            assert_eq!(next_chunk_index, 1);
            assert!(
                complete,
                "a single chunk covering the whole length completes"
            );
            assert!(
                idle_timeout_ms > 0,
                "the peer must be told the deadline it is held to"
            );
        }
        other => panic!("unexpected response to a bulk transfer chunk: {other:?}"),
    }
    // The bytes really are staged: they can be taken back out intact.
    assert_eq!(
        crate::daemon::bulk_staging::take(&reference).expect("staged bytes"),
        body
    );
}

/// A chunk whose body is not valid base64 is refused.
async fn assert_write_bulk_transfer_chunk_malformed() {
    let ctx = test_ctx();
    let error = dispatch_matrix_request(
        &ctx,
        Request::WriteBulkTransferChunk {
            transfer: archive_transfer_ref(b"body"),
            chunk_index: 0,
            data_base64: "not-base64".to_string(),
        },
    )
    .await
    .expect_err("an invalid chunk encoding is rejected");
    assert_eq!(error.code, ErrorCode::BadRequest);
}

async fn assert_import_session_archive_happy() {
    let ctx = test_ctx();
    // The default happy path is a redacted archive: it imports without any
    // raw acknowledgement and reports redacted provenance.
    let (session_id, archive_base64) = minimal_import_archive_base64(true);
    let archive_bytes = base64::engine::general_purpose::STANDARD
        .decode(archive_base64.as_bytes())
        .expect("fixture archive decodes");
    let response = dispatch_matrix_request(
        &ctx,
        Request::ImportSessionArchive {
            transfer: stage_archive_transfer(&archive_bytes),
            include_sensitive: false,
        },
    )
    .await
    .expect("valid archive imports");
    let imported = match response {
        Response::ImportSessionArchive {
            imported,
            redacted: true,
        } if imported.len() == 1 => imported[0],
        other => panic!("unexpected import response: {other:?}"),
    };
    assert_ne!(imported, session_id);
    assert!(ctx.db.get_session(imported).await.unwrap().is_some());

    // An unredacted archive fails closed without the explicit acknowledgement:
    // importing it would restore raw secret material without redaction custody.
    let (raw_source_id, raw_archive_base64) = minimal_import_archive_base64(false);
    let raw_archive_bytes = base64::engine::general_purpose::STANDARD
        .decode(raw_archive_base64.as_bytes())
        .expect("fixture archive decodes");
    let refusal = dispatch_matrix_request(
        &ctx,
        Request::ImportSessionArchive {
            transfer: stage_archive_transfer(&raw_archive_bytes),
            include_sensitive: false,
        },
    )
    .await
    .expect_err("an unredacted archive must require the include-sensitive acknowledgement");
    assert_eq!(refusal.code, ErrorCode::BadRequest);
    assert!(
        refusal.message.contains("--include-sensitive"),
        "refusal must name the acknowledgement it requires: {}",
        refusal.message
    );

    // With the acknowledgement the raw archive imports and reports that its
    // content is unredacted, so the custody drop is never silent.
    let response = dispatch_matrix_request(
        &ctx,
        Request::ImportSessionArchive {
            transfer: stage_archive_transfer(&raw_archive_bytes),
            include_sensitive: true,
        },
    )
    .await
    .expect("acknowledged unredacted archive imports");
    match response {
        Response::ImportSessionArchive {
            imported,
            redacted: false,
        } if imported.len() == 1 => assert_ne!(imported[0], raw_source_id),
        other => panic!("unexpected import response: {other:?}"),
    }
}

