async fn assert_session_db_mutating_happy(kind: &str) {
    let ctx = test_ctx();
    let tmp = tempfile::tempdir().unwrap();
    let session = Session::insert_row_for_test(
        &ctx.db,
        tmp.path(),
        "Build",
        crate::session::TestSessionRowOptions::default(),
    )
    .await
    .unwrap();
    match kind {
        "archive_session" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::ArchiveSession {
                    session_id: session.session_id,
                    cascade: false,
                },
            )
            .await
            .expect("archive session");
            assert!(matches!(response, Response::Ack));
            assert!(
                ctx.db
                    .get_session(session.session_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .archived_at_unix_ms
                    .is_some()
            );
        }
        "unarchive_session" => {
            ctx.db
                .archive_session(session.session_id, false)
                .await
                .unwrap();
            let response = dispatch_matrix_request(
                &ctx,
                Request::UnarchiveSession {
                    session_id: session.session_id,
                },
            )
            .await
            .expect("unarchive session");
            assert!(matches!(response, Response::Ack));
            assert!(
                ctx.db
                    .get_session(session.session_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .archived_at_unix_ms
                    .is_none()
            );
        }
        "fork_session" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::ForkSession {
                    parent_session_id: session.session_id,
                    fork_point_turn_id: None,
                    ephemeral: false,
                    fresh_thread: false,
                },
            )
            .await
            .expect("fork session");
            let Response::Forked {
                session_id: fork_id,
                parent_session_id,
                ..
            } = response
            else {
                panic!("expected Forked");
            };
            assert_eq!(parent_session_id, session.session_id);
            assert_eq!(
                ctx.db
                    .get_session(fork_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .parent_session_id,
                Some(session.session_id)
            );
        }
        "discard_session" => {
            let fork = ctx
                .db
                .create_ephemeral_fork(session.session_id, None)
                .await
                .unwrap();
            let response = dispatch_matrix_request(
                &ctx,
                Request::DiscardSession {
                    session_id: fork.session_id,
                },
            )
            .await
            .expect("discard ephemeral session");
            assert!(matches!(response, Response::Ack));
            assert!(ctx.db.get_session(fork.session_id).await.unwrap().is_none());
        }
        "btw_create" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::CreateBtwFork {
                    parent_session_id: session.session_id,
                    tangent: false,
                },
            )
            .await
            .expect("create btw fork");
            let Response::BtwFork { info, created } = response else {
                panic!("expected BtwFork");
            };
            assert!(created);
            assert_eq!(info.parent_session_id, session.session_id);
            assert!(ctx.db.get_session(info.session_id).await.unwrap().is_some());
        }
        "btw_end" => {
            let fork = ctx
                .db
                .create_btw_fork(session.session_id, false)
                .await
                .unwrap();
            let response = dispatch_matrix_request(
                &ctx,
                Request::EndBtwFork {
                    parent_session_id: session.session_id,
                },
            )
            .await
            .expect("end btw fork");
            assert!(matches!(response, Response::Ack));
            assert!(
                ctx.db
                    .get_session(fork.info.session_id)
                    .await
                    .unwrap()
                    .is_none()
            );
        }
        "rename_session" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::RenameSession {
                    session_id: session.session_id,
                    title: "New title".into(),
                },
            )
            .await
            .expect("rename session");
            assert!(matches!(response, Response::Ack));
            assert_eq!(
                ctx.db
                    .get_session(session.session_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .title,
                Some("New title".into())
            );
        }
        "share_session" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::ShareSession {
                    session_id: session.session_id,
                    shared: true,
                },
            )
            .await
            .expect("share session");
            assert!(matches!(response, Response::Ack));
            assert!(
                ctx.db
                    .get_session(session.session_id)
                    .await
                    .unwrap()
                    .unwrap()
                    .shared_with_collaborators
            );
        }
        "record_session_note" => {
            let response = dispatch_matrix_request(
                &ctx,
                Request::RecordSessionNote {
                    session_id: session.session_id,
                    text: "note".into(),
                },
            )
            .await
            .expect("record note");
            let Response::NoteRecorded { seq } = response else {
                panic!("expected NoteRecorded");
            };
            assert!(seq > 0);
            let events = ctx
                .db
                .list_session_events(session.session_id)
                .await
                .unwrap();
            assert!(events.iter().any(|event| {
                event.kind == "user_note"
                    && event.data.get("text").and_then(|v| v.as_str()) == Some("note")
            }));
        }
        "delete_session" => {
            // v10: DeleteSession rejects active sessions; end it first.
            ctx.db.end_session(session.session_id).await.unwrap();
            let response = dispatch_matrix_request(
                &ctx,
                Request::DeleteSession {
                    session_id: session.session_id,
                },
            )
            .await
            .expect("delete session");
            assert!(matches!(response, Response::Ack));
            assert!(
                ctx.db
                    .get_session(session.session_id)
                    .await
                    .unwrap()
                    .is_none()
            );
        }
        _ => unreachable!(),
    }
}

