#[tokio::test]
async fn client_transport_executor_error_wins_over_dependent_clean_writer_exit() {
    let (writer_lifetime, writer_closed) = tokio::sync::oneshot::channel::<()>();
    let mut executor = tokio::spawn(async move {
        drop(writer_lifetime);
        Err::<(), _>(anyhow::anyhow!("forced executor failure"))
    });
    let mut writer = tokio::spawn(async move {
        let _ = writer_closed.await;
        Ok::<(), anyhow::Error>(())
    });
    let mut reader = tokio::spawn(std::future::pending::<anyhow::Result<()>>());
    let mut event = tokio::spawn(std::future::pending::<anyhow::Result<()>>());

    let error = super::select_client_task(&mut reader, &mut writer, &mut event, &mut executor)
        .await
        .result
        .unwrap_err();
    reader.abort();
    writer.abort();
    event.abort();
    executor.abort();
    assert_eq!(
        format!("{error:#}"),
        "client executor task failed: forced executor failure"
    );
}

#[tokio::test]
async fn server_responses_use_negotiated_client_protocol_version() {
    let ctx = test_ctx();
    let (server_stream, client_stream) = test_stream_pair();
    let server = tokio::spawn(handle_client_transport_as(
        server_stream,
        ctx,
        ClientPrincipal::owner(),
        Uuid::new_v4(),
        false,
    ));
    let mut client =
        ProtoStream::with_version(client_stream, proto::MIN_SUPPORTED_PROTOCOL_VERSION);

    // The hello is intentionally emitted at the daemon's current protocol so
    // older clients can parse it as a raw handshake before negotiation.
    let _ = recv_body(&mut client).await;

    let status_id = Uuid::new_v4();
    client
        .send(&Envelope::request_at(
            proto::MIN_SUPPORTED_PROTOCOL_VERSION,
            status_id,
            Request::DaemonStatus,
        ))
        .await
        .unwrap();

    loop {
        match client.recv().await.unwrap().unwrap() {
            RecvFrame::Envelope(env) => {
                assert_eq!(env.v, proto::MIN_SUPPORTED_PROTOCOL_VERSION);
                match env.body {
                    Body::Event { .. } => continue,
                    Body::Response { id, response } => {
                        assert_eq!(id, status_id);
                        assert!(matches!(*response, Response::DaemonStatus { .. }));
                        break;
                    }
                    other => panic!("expected daemon status response, got {other:?}"),
                }
            }
            other => panic!("expected negotiated response envelope, got {other:?}"),
        }
    }

    drop(client);
    server.await.unwrap().unwrap();
}

