// ---------------------------------------------------------------------------
// Attempt-grant ceiling authorization (AC7 / AC3a)
// ---------------------------------------------------------------------------

#[cfg(feature = "remote")]
fn attempt_grant_test_ctx(
    resolver: Arc<dyn crate::daemon::remote_project_resolver::RemoteProjectResolver>,
) -> Arc<DaemonContext> {
    let db = Db::open_in_memory().expect("in-memory db");
    let locks = Arc::new(LockManager::in_memory(db.clone()));
    let paths = DaemonPaths {
        socket: std::path::PathBuf::from("/tmp/cockpit-attempt-grant-test.sock"),
        pid_file: std::path::PathBuf::from("/tmp/cockpit-attempt-grant-test.pid"),
        ephemeral: true,
    };
    Arc::new(
        DaemonContext::new(
            db,
            locks,
            paths,
            crate::daemon::terminal::test_host_factory(),
            stub_config_source(),
        )
        .with_remote_project_resolver(resolver),
    )
}

#[cfg(feature = "remote")]
fn attempt_grant_principal(
    ceiling: cockpit_proto::remote_public_service_policy::RemotePermissionCeilingV1,
) -> ClientPrincipal {
    use crate::daemon::principal::{
        AttemptGrantAuthorization, GrantDeviceBinding, RemoteCeilingAuthorization,
    };
    ClientPrincipal::from_attempt_grant(
        "attempt-grant-alias".to_string(),
        AttemptGrantAuthorization {
            account_alias: "attempt-grant-alias".to_string(),
            ceiling: RemoteCeilingAuthorization {
                attachment_capabilities: ceiling.attachment_capabilities,
                projects: ceiling.projects,
            },
            device_binding: GrantDeviceBinding {
                client_device_id: [1u8; 16],
                client_certificate_id: [2u8; 16],
                client_generation: 1,
                logical_attachment_id: [3u8; 16],
                child_attempt_id: [4u8; 16],
            },
        },
        None,
    )
}

/// AC7 / AC3a — a read-only attempt-grant ceiling denies every write category
/// through the production `authorize_request` entry point, while a write-capable
/// ceiling permits the same requests; a resolver miss fails closed.
#[tokio::test]
#[cfg(feature = "remote")]
async fn remote_attempt_readonly_ceiling_denies_write() {
    use cockpit_proto::remote_public_service_policy::{
        RemoteAttachmentCapabilityV1 as Att, RemotePermissionCeilingV1,
        RemoteProjectCapabilityV1 as Proj,
    };

    let tmp = tempfile::tempdir().unwrap();
    let canonical_root = tmp.path().canonicalize().unwrap();
    let project_id = [0x11u8; 16];
    let resolver = Arc::new(
        crate::daemon::remote_project_resolver::StaticRemoteProjectResolver::new()
            .with_mapping(canonical_root.clone(), project_id),
    );
    let ctx = attempt_grant_test_ctx(resolver);

    // Attach to a session rooted at the mapped project so `session_writer`
    // resolves the session's project root through the resolver.
    let (mut state, _session_id) = attached_state(&ctx, tmp.path()).await;
    let root_text = tmp.path().to_string_lossy().into_owned();

    let fs_read = || Request::FsRead {
        project_root: root_text.clone(),
        path: "readme.md".into(),
        base64: false,
    };
    let fs_write = || Request::FsWrite {
        project_root: root_text.clone(),
        path: "readme.md".into(),
        content: "next".into(),
        base_hash: None,
    };
    let open_terminal = || Request::OpenTerminal {
        cwd: Some(root_text.clone()),
        cols: 80,
        rows: 24,
    };

    // --- Read-only ceiling: only read capabilities present. -----------------
    let readonly = RemotePermissionCeilingV1 {
        attachment_capabilities: vec![Att::AttachmentRead],
        projects: vec![(
            project_id,
            vec![Proj::ProjectRead, Proj::FilesystemRead, Proj::SessionRead],
        )],
    };
    state.principal = attempt_grant_principal(readonly);

    // read_only_without_project is always permitted (admission is the gate).
    authorize_request(&Request::DaemonStatus, &state, &ctx)
        .await
        .expect("read_only_without_project request is permitted");

    // A read-capability project request (fs_read → FilesystemRead) is permitted.
    authorize_request(&fs_read(), &state, &ctx)
        .await
        .expect("read-only ceiling permits FilesystemRead");

    // session_writer (cancel_turn → project SessionWrite=8) is DENIED.
    let err = authorize_request(&Request::CancelTurn, &state, &ctx)
        .await
        .expect_err("read-only ceiling denies SessionWrite-class request");
    assert_eq!(err.code, ErrorCode::Authorization);

    // project_capability write (fs_write → FilesystemWrite=4) is DENIED.
    let err = authorize_request(&fs_write(), &state, &ctx)
        .await
        .expect_err("read-only ceiling denies FilesystemWrite");
    assert_eq!(err.code, ErrorCode::Authorization);

    // attachment_capability request (open_terminal → AttachmentManageChildren)
    // is DENIED when the mapped attachment ordinal is absent.
    let err = authorize_request(&open_terminal(), &state, &ctx)
        .await
        .expect_err("read-only ceiling denies attachment-capability request");
    assert_eq!(err.code, ErrorCode::Authorization);

    // --- Write-capable ceiling: the same writes are now permitted. ----------
    let writable = RemotePermissionCeilingV1 {
        attachment_capabilities: vec![Att::AttachmentRead, Att::AttachmentManageChildren],
        projects: vec![(
            project_id,
            vec![
                Proj::FilesystemRead,
                Proj::FilesystemWrite,
                Proj::SessionRead,
                Proj::SessionWrite,
            ],
        )],
    };
    state.principal = attempt_grant_principal(writable);

    authorize_request(&Request::CancelTurn, &state, &ctx)
        .await
        .expect("SessionWrite ceiling permits session_writer request");
    authorize_request(&fs_write(), &state, &ctx)
        .await
        .expect("FilesystemWrite ceiling permits fs_write");
    authorize_request(&open_terminal(), &state, &ctx)
        .await
        .expect("AttachmentManageChildren ceiling permits terminal request");

    // A *mutating* public_read command (cancel_run_invocation) is scopeless, so
    // it maps to no ceiling capability and is denied even under this fully
    // write-capable ceiling — a scopeless mutation must never bypass the ceiling.
    let cancel_invocation = Request::CancelRunInvocation {
        client_submission_id: Uuid::now_v7(),
    };
    let err = authorize_request(&cancel_invocation, &state, &ctx)
        .await
        .expect_err("mutating public_read is denied for attempt grants");
    assert_eq!(err.code, ErrorCode::Authorization);

    // --- Resolver miss fails closed even with a fully-capable ceiling. ------
    let unmapped_root = tempfile::tempdir().unwrap();
    let unmapped_write = Request::FsWrite {
        project_root: unmapped_root.path().to_string_lossy().into_owned(),
        path: "x.txt".into(),
        content: "y".into(),
        base_hash: None,
    };
    let err = authorize_request(&unmapped_write, &state, &ctx)
        .await
        .expect_err("resolver miss must fail closed");
    assert_eq!(err.code, ErrorCode::Authorization);

    // An attempt-grant principal is never Owner.
    assert!(!state.principal.is_owner());
}

// ---- sealed-owner value channel: production backing + session binding -------

/// Drive one owner request through the serialized dispatch path.
async fn dispatch_sealed_owner(
    ctx: &Arc<DaemonContext>,
    state: &mut MutableClientState,
    request: Request,
) -> std::result::Result<Response, ErrorPayload> {
    let shared = state.shared_snapshot();
    let mut effects = ClientRequestEffects::default();
    handle_serialized_request(request, state, &shared, ctx, &mut effects).await
}

/// Create a project-scoped sealed value end-to-end and return its record id.
async fn create_project_sealed_value(
    ctx: &Arc<DaemonContext>,
    state: &mut MutableClientState,
    name: &str,
    literal: &str,
) -> String {
    let begun = dispatch_sealed_owner(
        ctx,
        state,
        Request::BeginSealedOwnerOperation {
            disposition: "create".into(),
            record_id: None,
            name: Some(name.into()),
            description: Some("Deploy token".into()),
            scope_kind: Some("project".into()),
            scope_key: Some("/repo".into()),
        },
    )
    .await
    .expect("begin create");
    let capability_id = match begun {
        Response::SealedOwnerOperationBegun { capability_id, .. } => capability_id,
        other => panic!("expected begun, got {other:?}"),
    };
    let applied = dispatch_sealed_owner(
        ctx,
        state,
        Request::ApplySealedOwnerOperation {
            capability_id,
            literal: Some(proto::SensitiveWireLiteral::new(literal.into())),
        },
    )
    .await
    .expect("apply create write");
    assert!(matches!(
        applied,
        Response::SealedOwnerOperationApplied {
            revealed_literal: None
        }
    ));

    let inventory = dispatch_sealed_owner(
        ctx,
        state,
        Request::SealedOwnerInventory {
            scope_kind: Some("project".into()),
            scope_key: Some("/repo".into()),
        },
    )
    .await
    .expect("inventory");
    match inventory {
        Response::SealedOwnerInventory { items, .. } => {
            let item = items
                .iter()
                .find(|item| item.name == name)
                .expect("created value present in inventory");
            item.record_id.clone()
        }
        other => panic!("expected inventory, got {other:?}"),
    }
}

#[tokio::test]
async fn production_directory_and_capability_table_installed() {
    const LITERAL: &str = "sk-live-9f2c41ab77de4c0b83e5aa16d9c7b204";
    let ctx = test_ctx();
    let mut state = owner_state();

    let record_id = create_project_sealed_value(&ctx, &mut state, "deploy_token", LITERAL).await;

    // Recover succeeds only because the directory + capability table are wired.
    let begun = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::BeginSealedOwnerOperation {
            disposition: "recover".into(),
            record_id: Some(record_id.clone()),
            name: None,
            description: None,
            scope_kind: None,
            scope_key: None,
        },
    )
    .await
    .expect("begin recover");
    let capability_id = match begun {
        Response::SealedOwnerOperationBegun { capability_id, .. } => capability_id,
        other => panic!("expected begun, got {other:?}"),
    };
    let applied = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::ApplySealedOwnerOperation {
            capability_id,
            literal: None,
        },
    )
    .await
    .expect("apply recover");
    match applied {
        Response::SealedOwnerOperationApplied {
            revealed_literal: Some(literal),
        } => assert_eq!(literal.as_str(), LITERAL),
        other => panic!("expected revealed literal, got {other:?}"),
    }

    // The recover audit committed before the reveal was returned.
    let rows = ctx
        .db
        .sealed_recovery_audit_for_record(record_id)
        .await
        .unwrap();
    assert_eq!(rows.len(), 1, "one revealed audit row");
    assert_eq!(
        rows[0].outcome,
        crate::db::sealed_actions::SealedRecoveryOutcome::Revealed
    );
}

#[tokio::test]
async fn sealed_capability_minted_in_one_session_is_rejected_in_another() {
    const LITERAL: &str = "sk-live-session-bound-6d9c7b204aa16";
    let ctx = test_ctx();
    let instance_a = Uuid::new_v4();
    let instance_b = Uuid::new_v4();

    let mut state_a = owner_state_with_instance(instance_a);
    let record_id = create_project_sealed_value(&ctx, &mut state_a, "session_bound", LITERAL).await;

    // Mint a recover capability in connection A.
    let begun = dispatch_sealed_owner(
        &ctx,
        &mut state_a,
        Request::BeginSealedOwnerOperation {
            disposition: "recover".into(),
            record_id: Some(record_id),
            name: None,
            description: None,
            scope_kind: None,
            scope_key: None,
        },
    )
    .await
    .expect("begin recover in A");
    let capability_id = match begun {
        Response::SealedOwnerOperationBegun { capability_id, .. } => capability_id,
        other => panic!("expected begun, got {other:?}"),
    };

    // Applying it from connection B is rejected fail-closed and reveals nothing.
    let mut state_b = owner_state_with_instance(instance_b);
    let err = dispatch_sealed_owner(
        &ctx,
        &mut state_b,
        Request::ApplySealedOwnerOperation {
            capability_id: capability_id.clone(),
            literal: None,
        },
    )
    .await
    .expect_err("cross-session apply must be rejected");
    assert!(
        err.message.contains("different session"),
        "unexpected error: {err:?}"
    );

    // The capability was NOT spent by the rejected cross-session apply: the
    // minting connection A can still use it.
    let applied = dispatch_sealed_owner(
        &ctx,
        &mut state_a,
        Request::ApplySealedOwnerOperation {
            capability_id,
            literal: None,
        },
    )
    .await
    .expect("apply recover in A");
    match applied {
        Response::SealedOwnerOperationApplied {
            revealed_literal: Some(literal),
        } => assert_eq!(literal.as_str(), LITERAL),
        other => panic!("expected revealed literal, got {other:?}"),
    }
}

#[tokio::test]
async fn sealed_action_channel_create_list_revise_retire_roundtrip() {
    let ctx = test_ctx();
    let mut state = owner_state();

    // Create through the owner-declared fixed sink. Models never receive this
    // declaration; they later interact only through the minted action id.
    let created = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::CreateDeclaredSealedAction {
            project_id: "proj".into(),
            description: "notify deploy".into(),
            declaration: proto::SealedActionDeclaration::CommandArgument {
                argv: vec!["notify".into(), "{{sealed_value}}".into()],
            },
        },
    )
    .await
    .expect("create sealed action");
    let action_id = match created {
        Response::SealedActionCreated {
            action_id,
            revision,
        } => {
            assert_eq!(revision, 1);
            uuid::Uuid::parse_str(&action_id).expect("daemon-minted uuid");
            action_id
        }
        other => panic!("expected created, got {other:?}"),
    };

    // List reflects it, enabled at revision 1.
    let listed = dispatch_sealed_owner(&ctx, &mut state, Request::ListSealedActions)
        .await
        .expect("list sealed actions");
    match listed {
        Response::SealedActions { actions } => {
            let row = actions
                .iter()
                .find(|a| a.action_id == action_id)
                .expect("created action present");
            assert!(row.enabled);
            assert_eq!(row.revision, 1);
        }
        other => panic!("expected actions, got {other:?}"),
    }

    // Disable → new revision.
    let revised = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::ReviseSealedActionEnabled {
            action_id: action_id.clone(),
            enabled: false,
        },
    )
    .await
    .expect("revise sealed action");
    match revised {
        Response::SealedActionRevised { revision, .. } => assert_eq!(revision, 2),
        other => panic!("expected revised, got {other:?}"),
    }

    // Retire (confirm must match).
    let retired = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::RetireSealedAction {
            action_id: action_id.clone(),
            confirm: action_id.clone(),
        },
    )
    .await
    .expect("retire sealed action");
    assert!(matches!(
        retired,
        Response::SealedActionRetired { retired: true, .. }
    ));

    // A retire whose confirm does not match the id is a content-free bad request.
    let err = dispatch_sealed_owner(
        &ctx,
        &mut state,
        Request::RetireSealedAction {
            action_id: "one".into(),
            confirm: "two".into(),
        },
    )
    .await
    .expect_err("mismatched retire confirmation must reject");
    assert_eq!(err.code, ErrorCode::BadRequest);
}

