// ---- Daemon-startup command-backed secret resolution (inc 2) -------------

/// Counting executor for the startup-resolution tests: records invocations and
/// returns a canned success or a canned failure.
struct StartupCountingExecutor {
    outcome: std::result::Result<String, crate::secret_command::CommandSecretError>,
    calls: std::sync::atomic::AtomicUsize,
}

impl StartupCountingExecutor {
    fn ok(value: &str) -> std::sync::Arc<Self> {
        std::sync::Arc::new(Self {
            outcome: Ok(value.to_string()),
            calls: std::sync::atomic::AtomicUsize::new(0),
        })
    }

    fn failing(error: crate::secret_command::CommandSecretError) -> std::sync::Arc<Self> {
        std::sync::Arc::new(Self {
            outcome: Err(error),
            calls: std::sync::atomic::AtomicUsize::new(0),
        })
    }
}

#[async_trait::async_trait]
impl crate::secret_command::CommandSecretExecutor for StartupCountingExecutor {
    async fn run(
        &self,
        _argv: &[String],
    ) -> std::result::Result<String, crate::secret_command::CommandSecretError> {
        self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        self.outcome.clone()
    }
}

fn startup_ctx_referencing_command_secret(secret_name: &str) -> std::sync::Arc<DaemonContext> {
    use crate::config::providers::{
        ActiveModelRef, HeaderSpec, ModelEntry, ProviderEntry, ProvidersConfig,
    };
    let mut providers = ProvidersConfig::default();
    providers.providers.insert(
        "lmstudio".to_string(),
        ProviderEntry {
            url: "http://localhost:1/v1".to_string(),
            models: vec![ModelEntry {
                id: "m".to_string(),
                ..ModelEntry::default()
            }],
            headers: vec![HeaderSpec {
                name: "Authorization".to_string(),
                value: format!("Bearer $secret:{secret_name}"),
            }],
            ..ProviderEntry::default()
        },
    );
    providers.active_model = Some(ActiveModelRef {
        provider: "lmstudio".to_string(),
        model: "m".to_string(),
        reasoning_effort: None,
        thinking_mode: None,
        prompt_cache_retention: None,
    });
    test_ctx_with_config_source(crate::daemon::config_source::ConfigSource::fixed(
        providers,
        crate::config::extended::ExtendedConfig::default(),
    ))
}

/// Claim `(provider, cwd)` ownership of `item_id` so the owner-scoped startup
/// resolution (keyed on `std::env::current_dir()`) resolves it. Read-only w.r.t.
/// the process cwd — never mutates it.
fn claim_current_dir_ownership(db: &crate::db::Db, item_id: &str) {
    let cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"));
    let root = crate::secret_ownership::canonical_owner_root(&cwd.display().to_string());
    let item_id = item_id.to_string();
    db.blocking_write_for_sync_maintenance(move |conn| {
        conn.execute(
            "INSERT INTO secret_named_ownership (item_id, owner_kind, project_root, created_at)
             VALUES (?1, 'provider', ?2, 0)",
            rusqlite::params![item_id, root],
        )?;
        Ok(())
    })
    .unwrap();
}

/// Mark the process cwd as a TRUSTED workspace in `db`, so startup resolution
/// (which resolves the trust policy from the DB for `current_dir()` and loads
/// via the trust-aware daemon loader) does not fail-closed on an unset/untrusted
/// workspace. Trust is keyed on the SAME resolved root that
/// `resolve_workspace_trust_policy_from_db` queries — `resolve_trust_root` walks
/// to the git worktree root, so trusting the raw cwd would miss. Writes only to
/// the test's own DB.
async fn trust_current_dir(db: &crate::db::Db) {
    let cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"));
    let root = crate::config::trust::resolve_trust_root(&cwd).expect("resolve trust root for cwd");
    db.set_workspace_trust(
        &root.root,
        crate::db::workspace_trust::WorkspaceTrustMode::Trust,
    )
    .await
    .unwrap();
}

/// AC3: a referenced, provider-owned command-backed secret is `Resolved` after
/// startup resolution (which `boot_with_db` runs) in a TRUSTED workspace.
#[tokio::test]
async fn daemon_startup_resolves_referenced_command_secrets() {
    let ctx = startup_ctx_referencing_command_secret("startupcmd");
    let mut store =
        crate::credentials::CredentialStore::from_vault(ctx.secret_vault.clone()).unwrap();
    store
        .set_named_secret_command("startupcmd", vec!["prog".to_string()])
        .unwrap();
    store.save().unwrap();
    claim_current_dir_ownership(&ctx.db, "startupcmd");
    trust_current_dir(&ctx.db).await;

    let cache = crate::secret_command::CommandSecretCache::new(StartupCountingExecutor::ok(
        "startup-resolved-token-abcdef0123456789",
    ));
    ctx.registry.set_command_secret_cache(cache.clone());

    ctx.resolve_startup_command_secrets().await;

    assert!(
        matches!(
            cache.status("startupcmd"),
            Some(crate::secret_command::CommandResolutionStatus::Resolved)
        ),
        "a referenced command secret must be Resolved after startup"
    );
    assert_eq!(cache.exec_count(), 1);
}

/// AC3: a failing startup resolution lands as `Failed` and never fails boot
/// (the resolution completes without panicking / returning an error).
#[tokio::test]
async fn daemon_startup_command_secret_failure_does_not_fail_boot() {
    let ctx = startup_ctx_referencing_command_secret("startupcmd");
    let mut store =
        crate::credentials::CredentialStore::from_vault(ctx.secret_vault.clone()).unwrap();
    store
        .set_named_secret_command("startupcmd", vec!["prog".to_string()])
        .unwrap();
    store.save().unwrap();
    claim_current_dir_ownership(&ctx.db, "startupcmd");
    trust_current_dir(&ctx.db).await;

    let cache = crate::secret_command::CommandSecretCache::new(StartupCountingExecutor::failing(
        crate::secret_command::CommandSecretError::NotFound,
    ));
    ctx.registry.set_command_secret_cache(cache.clone());

    // Completes normally: startup resolution never fails boot on a command error.
    ctx.resolve_startup_command_secrets().await;

    assert!(
        matches!(
            cache.status("startupcmd"),
            Some(crate::secret_command::CommandResolutionStatus::Failed(_))
        ),
        "a failing referenced command secret must land as Failed after startup"
    );
    assert_eq!(cache.exec_count(), 1);
}

/// HIGH #3a (part 1): an UNSET/untrusted workspace fails closed — startup
/// resolution resolves the trust policy from the DB, and with no trust decision
/// it never loads project config or execs. The FIXED source WOULD return the
/// reference if consulted, so a `0` exec count proves the trust gate exists (an
/// implementation that skipped the trust check would exec 1).
#[tokio::test]
async fn daemon_startup_untrusted_workspace_does_not_exec_command() {
    let ctx = startup_ctx_referencing_command_secret("trustcmd");
    let mut store =
        crate::credentials::CredentialStore::from_vault(ctx.secret_vault.clone()).unwrap();
    store
        .set_named_secret_command("trustcmd", vec!["prog".to_string()])
        .unwrap();
    store.save().unwrap();
    // Ownership is claimed so the ONLY thing preventing execution is the
    // (absent) workspace trust decision — no `trust_current_dir` call here.
    claim_current_dir_ownership(&ctx.db, "trustcmd");

    let cache = crate::secret_command::CommandSecretCache::new(StartupCountingExecutor::ok(
        "must-never-be-produced-token",
    ));
    ctx.registry.set_command_secret_cache(cache.clone());

    ctx.resolve_startup_command_secrets().await;

    assert_eq!(
        cache.exec_count(),
        0,
        "an untrusted / unset workspace must never exec a project command reference at boot"
    );
    assert!(cache.status("trustcmd").is_none());
}

/// HIGH #3a (part 2): startup resolution loads through the TRUST-AWARE daemon
/// loader (`load_effective_for_daemon` → `daemon_load`), NOT the trust-blind
/// `load`. With a TRUSTED workspace (so trust resolution succeeds), a source
/// whose trust-blind `load` references the command secret while its trust-aware
/// `daemon_load` returns empty (the dropped-project-layer shape) must exec 0
/// times — an implementation that consulted `load` would exec 1.
#[tokio::test]
async fn daemon_startup_uses_trust_aware_daemon_loader() {
    use crate::config::providers::{
        ActiveModelRef, HeaderSpec, ModelEntry, ProviderEntry, ProvidersConfig,
    };
    let mut referencing = ProvidersConfig::default();
    referencing.providers.insert(
        "lmstudio".to_string(),
        ProviderEntry {
            url: "http://localhost:1/v1".to_string(),
            models: vec![ModelEntry {
                id: "m".to_string(),
                ..ModelEntry::default()
            }],
            headers: vec![HeaderSpec {
                name: "Authorization".to_string(),
                value: "Bearer $secret:trustcmd".to_string(),
            }],
            ..ProviderEntry::default()
        },
    );
    referencing.active_model = Some(ActiveModelRef {
        provider: "lmstudio".to_string(),
        model: "m".to_string(),
        reasoning_effort: None,
        thinking_mode: None,
        prompt_cache_retention: None,
    });
    let source = crate::daemon::config_source::ConfigSource::new_with_daemon_load(
        // Trust-blind `load`: references the command secret (what an unguarded
        // implementation would consult).
        move |_cwd| {
            Ok((
                referencing.clone(),
                crate::config::extended::ExtendedConfig::default(),
            ))
        },
        // Trust-aware `daemon_load`: models a dropped project layer (empty).
        |_cwd| {
            Ok(crate::daemon::config_source::DaemonConfigLoad {
                providers: crate::config::providers::ProvidersConfig::default(),
                provider_warnings: Vec::new(),
                extended: crate::config::extended::ExtendedConfig::default(),
                response_metrics_tokenizer_validation: Ok(()),
                participating_layers: Vec::new(),
            })
        },
        |_cwd, _provider| None,
        |_cwd| crate::daemon::config_source::ConfigWatchPaths::new(Vec::new(), Vec::new()),
    );
    let ctx = test_ctx_with_config_source(source);
    let mut store =
        crate::credentials::CredentialStore::from_vault(ctx.secret_vault.clone()).unwrap();
    store
        .set_named_secret_command("trustcmd", vec!["prog".to_string()])
        .unwrap();
    store.save().unwrap();
    claim_current_dir_ownership(&ctx.db, "trustcmd");
    // Trusted workspace, so trust resolution SUCCEEDS and the loader choice is
    // the only thing that matters.
    trust_current_dir(&ctx.db).await;

    let cache = crate::secret_command::CommandSecretCache::new(StartupCountingExecutor::ok(
        "must-never-be-produced-token",
    ));
    ctx.registry.set_command_secret_cache(cache.clone());

    ctx.resolve_startup_command_secrets().await;

    assert_eq!(
        cache.exec_count(),
        0,
        "startup must use the trust-aware daemon loader, not the trust-blind load"
    );
    assert!(cache.status("trustcmd").is_none());
}

/// MEDIUM (owner-scoping through the startup route): startup resolution reads
/// argv specs through an OWNER-SCOPED store, so a referenced command name owned
/// by a DIFFERENT workspace is never executed at boot. In a TRUSTED workspace
/// (so trust is not the reason for skipping) with the spec present but owned by
/// a foreign root, `resolve_startup_command_secrets` must exec 0 times — a
/// regression to an UNSCOPED vault lookup would find the spec and exec it once.
#[tokio::test]
async fn daemon_startup_does_not_exec_foreign_owned_command() {
    let ctx = startup_ctx_referencing_command_secret("foreignstartupcmd");
    let mut store =
        crate::credentials::CredentialStore::from_vault(ctx.secret_vault.clone()).unwrap();
    store
        .set_named_secret_command("foreignstartupcmd", vec!["prog".to_string()])
        .unwrap();
    store.save().unwrap();
    // Owned by a DIFFERENT workspace root, NOT this daemon's cwd — so the
    // owner-scoped startup view drops it.
    let foreign_root = crate::secret_ownership::canonical_owner_root("/some/other/workspace");
    ctx.db
        .blocking_write_for_sync_maintenance(move |conn| {
            conn.execute(
                "INSERT INTO secret_named_ownership (item_id, owner_kind, project_root, created_at)
                 VALUES ('foreignstartupcmd', 'provider', ?1, 0)",
                rusqlite::params![foreign_root],
            )?;
            Ok(())
        })
        .unwrap();
    // Trusted, so the ONLY thing preventing execution is owner-scoping.
    trust_current_dir(&ctx.db).await;

    let cache = crate::secret_command::CommandSecretCache::new(StartupCountingExecutor::ok(
        "must-never-be-produced-token",
    ));
    ctx.registry.set_command_secret_cache(cache.clone());

    ctx.resolve_startup_command_secrets().await;

    assert_eq!(
        cache.exec_count(),
        0,
        "startup must owner-scope: a foreign-owned command name is never execed"
    );
    assert!(cache.status("foreignstartupcmd").is_none());
}

/// #5(b): the REAL `boot_with_db` entry point runs startup command-secret
/// resolution. A trusted workspace + a fixed config that REFERENCES a
/// provider-owned command secret is injected, so the boot-path resolution must
/// leave a completed status (`Resolved`/`Failed`) in the daemon cache. Removing
/// the `resolve_startup_command_secrets` hook from `boot_with_db` makes the
/// status `None` and fails this test. (The argv is a nonexistent program, so the
/// real subprocess executor returns quickly with `Failed(NotFound)` — no hang.)
#[tokio::test]
async fn boot_with_db_resolves_referenced_command_secret() {
    let tmp = tempfile::tempdir().expect("tempdir");
    // In-memory DB so the pre-boot seed writes (spec save + ownership) take the
    // synchronous memory path — safe inside a tokio test — and the shared handle
    // is read by boot's own vault.
    let db = crate::db::Db::open_in_memory().expect("temp db");
    // Seed the vault (via the same opener boot uses), ownership, and trust
    // BEFORE boot, then boot with a fixed config that references the command.
    let vault = crate::secure_key::open_for_db(&db).expect("boot vault");
    let mut store = crate::credentials::CredentialStore::from_vault(vault).unwrap();
    store
        .set_named_secret_command(
            "bootcmd",
            vec!["cockpit-boot-command-secret-probe-nonexistent".to_string()],
        )
        .unwrap();
    store.save().unwrap();
    claim_current_dir_ownership(&db, "bootcmd");
    trust_current_dir(&db).await;

    let mut providers = crate::config::providers::ProvidersConfig::default();
    providers.providers.insert(
        "lmstudio".to_string(),
        crate::config::providers::ProviderEntry {
            url: "http://localhost:1/v1".to_string(),
            headers: vec![crate::config::providers::HeaderSpec {
                name: "Authorization".to_string(),
                value: "Bearer $secret:bootcmd".to_string(),
            }],
            ..crate::config::providers::ProviderEntry::default()
        },
    );
    let config_source = crate::daemon::config_source::ConfigSource::fixed(
        providers,
        crate::config::extended::ExtendedConfig::default(),
    );

    let mut timer = crate::startup::PhaseTimer::start("boot_resolves_referenced_command");
    let ctx = boot_with_db(
        DaemonPaths {
            socket: tmp.path().join("cockpit-cmd-boot.sock"),
            pid_file: tmp.path().join("cockpit-cmd-boot.pid"),
            ephemeral: true,
        },
        db,
        &mut timer,
        crate::daemon::terminal::test_host_factory(),
        config_source,
    )
    .await
    .expect("boot_with_db must succeed with startup command resolution wired in");

    assert!(
        ctx.registry
            .command_secret_cache()
            .status("bootcmd")
            .is_some(),
        "boot must run startup command-secret resolution for the referenced, \
         trusted, owned command secret"
    );
}

// `forked_session_inherits_command_secret_cache` moved to the driver tests
// (`engine::driver::tests::noninteractive`), where it drives the REAL
// `prepare_fork_task_context` production path instead of manually copying the
// cache onto a bare child session (which would pass even if the production copy
// were removed).

#[test]
fn interrupt_provenance_requires_successful_event_enqueue() {
    let interrupt_id = Uuid::new_v4();
    let event = proto::Event::InterruptRaised {
        session_id: Uuid::new_v4(),
        interrupt_id,
        agent: "builder".into(),
        description: "approve".into(),
        question: None,
        questions: None,
        pending_count: 1,
        reason: proto::InterruptRaiseReason::Initial,
    };
    let rendered = Arc::new(StdMutex::new(HashSet::new()));
    mark_rendered_interrupt_if_forwarded(&rendered, &event, false);
    assert!(!crate::sync::lock_or_recover(&rendered).contains(&interrupt_id));
    mark_rendered_interrupt_if_forwarded(&rendered, &event, true);
    assert!(crate::sync::lock_or_recover(&rendered).contains(&interrupt_id));

    let (tx, _rx) = tokio::sync::mpsc::channel(1);
    let mut lag = PendingEventLag::default();
    assert_eq!(
        try_send_in_process_event(&tx, event.clone(), None, &mut lag),
        InProcessEventSend::Enqueued
    );
    assert_eq!(
        try_send_in_process_event(&tx, event.clone(), None, &mut lag),
        InProcessEventSend::DroppedFull
    );
    drop(_rx);
    assert_eq!(
        try_send_in_process_event(&tx, event, None, &mut lag),
        InProcessEventSend::Closed
    );
}

#[tokio::test]
async fn socket_live_interrupt_provenance_tracks_the_attachment_that_received_the_event() {
    let ctx = test_ctx();
    let (session_tx, session_rx) = tokio::sync::broadcast::channel(8);
    let (event_cmd_tx, event_cmd_rx) = mpsc::channel(CLIENT_IO_CHANNEL_CAPACITY);
    let (executor_tx, _executor_rx) = mpsc::channel(CLIENT_IO_CHANNEL_CAPACITY);
    let (writer_tx, mut writer_rx) = mpsc::channel(CLIENT_IO_CHANNEL_CAPACITY);
    let old_rendered = Arc::new(StdMutex::new(HashSet::new()));
    let new_rendered = Arc::new(StdMutex::new(HashSet::new()));
    let session_id = Uuid::new_v4();
    let task = tokio::spawn(run_client_event_forwarder(
        ctx.clone(),
        ClientPrincipal::owner(),
        ctx.subscribe_global(),
        event_cmd_rx,
        executor_tx,
        writer_tx,
    ));
    event_cmd_tx
        .send(ClientEventCommand::Attach {
            session_id,
            rx: session_rx,
            rendered_interrupts: old_rendered.clone(),
        })
        .await
        .unwrap();

    let non_rendering_id = Uuid::new_v4();
    session_tx
        .send(test_event_envelope(proto::Event::Notice {
            session_id,
            text: non_rendering_id.to_string(),
        }))
        .unwrap();
    assert!(matches!(
        recv_writer_body(&mut writer_rx, "non-interrupt socket event").await,
        Body::Event {
            event: proto::Event::Notice { .. }
        }
    ));
    assert!(crate::sync::lock_or_recover(&old_rendered).is_empty());

    let old_interrupt_id = Uuid::new_v4();
    let old_event = proto::Event::InterruptRaised {
        session_id,
        interrupt_id: old_interrupt_id,
        agent: "builder".into(),
        description: "old attachment".into(),
        question: None,
        questions: None,
        pending_count: 1,
        reason: proto::InterruptRaiseReason::Initial,
    };
    session_tx.send(test_event_envelope(old_event)).unwrap();
    assert!(matches!(
        recv_writer_body(&mut writer_rx, "old attachment interrupt").await,
        Body::Event { event: proto::Event::InterruptRaised { interrupt_id, .. } }
            if interrupt_id == old_interrupt_id
    ));
    assert!(crate::sync::lock_or_recover(&old_rendered).contains(&old_interrupt_id));

    let new_session_rx = session_tx.subscribe();
    event_cmd_tx.send(ClientEventCommand::Detach).await.unwrap();
    event_cmd_tx
        .send(ClientEventCommand::Attach {
            session_id,
            rx: new_session_rx,
            rendered_interrupts: new_rendered.clone(),
        })
        .await
        .unwrap();
    tokio::task::yield_now().await;
    let new_interrupt_id = Uuid::new_v4();
    session_tx
        .send(test_event_envelope(proto::Event::InterruptRaised {
            session_id,
            interrupt_id: new_interrupt_id,
            agent: "builder".into(),
            description: "new attachment".into(),
            question: None,
            questions: None,
            pending_count: 1,
            reason: proto::InterruptRaiseReason::Initial,
        }))
        .unwrap();
    assert!(matches!(
        recv_writer_body(&mut writer_rx, "new attachment interrupt").await,
        Body::Event { event: proto::Event::InterruptRaised { interrupt_id, .. } }
            if interrupt_id == new_interrupt_id
    ));
    assert!(!crate::sync::lock_or_recover(&new_rendered).contains(&old_interrupt_id));
    assert!(crate::sync::lock_or_recover(&new_rendered).contains(&new_interrupt_id));

    drop(event_cmd_tx);
    task.await.unwrap();

    // A failed socket handoff must not mint rendering provenance. Closing the
    // real writer queue makes the production forwarder take its send-failure
    // branch before the mark call.
    let (session_tx, session_rx) = tokio::sync::broadcast::channel(1);
    let (event_cmd_tx, event_cmd_rx) = mpsc::channel(1);
    let (executor_tx, _executor_rx) = mpsc::channel(1);
    let (writer_tx, writer_rx) = mpsc::channel(1);
    drop(writer_rx);
    let failed_rendered = Arc::new(StdMutex::new(HashSet::new()));
    let failed_id = Uuid::new_v4();
    let failed_task = tokio::spawn(run_client_event_forwarder(
        ctx.clone(),
        ClientPrincipal::owner(),
        ctx.subscribe_global(),
        event_cmd_rx,
        executor_tx,
        writer_tx,
    ));
    event_cmd_tx
        .send(ClientEventCommand::Attach {
            session_id,
            rx: session_rx,
            rendered_interrupts: failed_rendered.clone(),
        })
        .await
        .unwrap();
    tokio::task::yield_now().await;
    session_tx
        .send(test_event_envelope(proto::Event::InterruptRaised {
            session_id,
            interrupt_id: failed_id,
            agent: "builder".into(),
            description: "failed handoff".into(),
            question: None,
            questions: None,
            pending_count: 1,
            reason: proto::InterruptRaiseReason::Initial,
        }))
        .unwrap();
    failed_task.await.unwrap();
    assert!(!crate::sync::lock_or_recover(&failed_rendered).contains(&failed_id));
}

#[derive(Clone)]
struct ProvenanceTestIo {
    fail_write: bool,
    written: Arc<StdMutex<Vec<u8>>>,
}

impl tokio::io::AsyncRead for ProvenanceTestIo {
    fn poll_read(
        self: std::pin::Pin<&mut Self>,
        _cx: &mut std::task::Context<'_>,
        _buf: &mut tokio::io::ReadBuf<'_>,
    ) -> std::task::Poll<io::Result<()>> {
        std::task::Poll::Pending
    }
}

impl tokio::io::AsyncWrite for ProvenanceTestIo {
    fn poll_write(
        self: std::pin::Pin<&mut Self>,
        _cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<io::Result<usize>> {
        if self.fail_write {
            return std::task::Poll::Ready(Err(io::Error::new(
                io::ErrorKind::BrokenPipe,
                "injected post-enqueue write failure",
            )));
        }
        crate::sync::lock_or_recover(&self.written).extend_from_slice(buf);
        std::task::Poll::Ready(Ok(buf.len()))
    }

    fn poll_flush(
        self: std::pin::Pin<&mut Self>,
        _cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<io::Result<()>> {
        std::task::Poll::Ready(Ok(()))
    }

    fn poll_shutdown(
        self: std::pin::Pin<&mut Self>,
        _cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<io::Result<()>> {
        std::task::Poll::Ready(Ok(()))
    }
}

#[tokio::test]
async fn socket_interrupt_provenance_requires_actual_proto_write_success() {
    for fail_write in [false, true] {
        let interrupt_id = Uuid::new_v4();
        let event = proto::Event::InterruptRaised {
            session_id: Uuid::new_v4(),
            interrupt_id,
            agent: "builder".into(),
            description: "actual writer outcome".into(),
            question: None,
            questions: None,
            pending_count: 1,
            reason: proto::InterruptRaiseReason::Initial,
        };
        let rendered = Arc::new(StdMutex::new(HashSet::new()));
        let written = Arc::new(StdMutex::new(Vec::new()));
        let stream = ProvenanceTestIo {
            fail_write,
            written: written.clone(),
        };
        let (_reader, writer) = ProtoStream::new(stream).into_split();
        let (writer_tx, writer_rx) = mpsc::channel(1);
        let writer_task = tokio::spawn(run_client_writer(writer, writer_rx));

        let delivered =
            send_socket_event_and_mark_rendered(&writer_tx, Some(&rendered), event).await;
        drop(writer_tx);
        writer_task.await.unwrap();

        assert_eq!(delivered, !fail_write);
        assert_eq!(
            crate::sync::lock_or_recover(&rendered).contains(&interrupt_id),
            !fail_write,
            "rendered provenance must follow the actual ProtoWriteHalf::send result"
        );
        assert_eq!(
            crate::sync::lock_or_recover(&written).is_empty(),
            fail_write,
            "the successful case must cross the real encoder/write seam"
        );
    }
}

async fn seed_governed_network_interrupt(db: &Db, session_id: Uuid) -> Uuid {
    let agent = match db.session_root_agent(session_id).await.unwrap() {
        Some(agent) => agent,
        None => {
            let created = db
                .create_agent_instance(
                    crate::db::agent_tree_decisions::NewAgentInstance {
                        session_id,
                        parent_agent_instance_id: None,
                        task_delegation_job_id: None,
                        task_delegation_child_uuid: None,
                        resolved_profile_snapshot_id: None,
                        workspace_ref: None,
                        auto_answer_enabled: false,
                    },
                    1,
                )
                .await
                .unwrap();
            match db
                .transition_agent_instance(
                    session_id,
                    created.agent_instance_id,
                    created.revision,
                    crate::db::agent_tree_decisions::AgentInstanceState::Running,
                    "{}",
                    2,
                )
                .await
                .unwrap()
            {
                crate::db::agent_tree_decisions::AgentTransitionOutcome::Transitioned(agent) => {
                    agent
                }
                outcome => panic!("unexpected root transition: {outcome:?}"),
            }
        }
    };
    let question = proto::InterruptQuestionSet {
        questions: vec![proto::InterruptQuestion::Single {
            prompt: "Approve exact Monty request?".into(),
            options: vec![proto::InterruptOption {
                id: "approve_once".into(),
                label: "Approve once".into(),
                description: None,
                secondary: false,
            }],
            allow_freetext: false,
            command_detail: None,
            permission: true,
            approval_class: None,
            sandbox_escalation: None,
        }],
    };
    let input = serde_json::json!({
        "wire_input": {
            "method": "POST",
            "url": "https://api.example.test/v1/items?limit=2",
            "headers": {"content-type": "application/json"},
            "body": "{}",
            "destination": "api.example.test",
        },
        "candidate_effects": [{"selection": "approve", "execute": {"wire_input": {
            "method": "POST",
            "url": "https://api.example.test/v1/items?limit=2",
            "headers": {"content-type": "application/json"},
            "body": "{}",
            "destination": "api.example.test",
        }}}],
    });
    let operation =
        crate::agent_tree::HostApprovalOperation::new("monty_network_egress", input).unwrap();
    let interrupt_id = db
        .raise_interrupt_questions_with_agent_instance_and_payload(
            session_id,
            "builder",
            Some(agent.agent_instance_id),
            "Monty POST request",
            &question,
            None,
        )
        .await
        .unwrap();
    db.reserve_host_approval_final_operation(
        session_id,
        agent.agent_instance_id,
        operation.operation_id,
        operation.operation_kind.clone(),
        operation.canonical_input_json.clone(),
        operation.input_digest.clone(),
        crate::agent_tree::HostApprovalAuthority::trusted_host().into_db(),
        3,
    )
    .await
    .unwrap();
    crate::agent_tree::AgentTreeLifecycle::new(db.clone())
        .request_decision_for_interrupt(
            session_id,
            crate::agent_tree::NewDecisionContract::user_question_interrupt(
                agent.agent_instance_id,
                agent.revision,
                &question,
                None,
            )
            .unwrap()
            .with_host_approval_subject(
                operation,
                crate::agent_tree::HostApprovalAuthority::trusted_host(),
            ),
            interrupt_id,
            3,
        )
        .await
        .unwrap();
    interrupt_id
}

#[tokio::test]
async fn resolve_interrupt_dispatch_threads_only_the_rendering_live_attachment_permit() {
    let ctx = test_ctx();
    let project = tempfile::tempdir().unwrap();
    let (mut state, session_id, mut work_rx) =
        attached_state_with_worker_receiver(&ctx, project.path()).await;
    let handle = state.attached.as_ref().unwrap().handle.clone();
    state.attached.as_mut().unwrap()._interactive_guard =
        Some(handle.register_interactive_client());
    let interrupt_id = seed_governed_network_interrupt(&ctx.db, session_id).await;
    crate::sync::lock_or_recover(&state.attached.as_ref().unwrap().rendered_interrupts)
        .insert(interrupt_id);
    let shared = state.shared_snapshot();
    let mut effects = ClientRequestEffects::default();
    let response = dispatch::handle_serialized_request(
        Request::ResolveInterrupt {
            interrupt_id,
            response: proto::ResolveResponse::Single {
                selected_id: "approve_once".into(),
            },
        },
        &mut state,
        &shared,
        &ctx,
        &mut effects,
    )
    .await
    .unwrap();
    assert!(matches!(response, Response::Ack));
    assert!(matches!(
        work_rx.recv().await.unwrap(),
        SessionWork::ResolveInterrupt {
            interrupt_id: delivered,
            governed_network_attachment: Some(_),
            ..
        } if delivered == interrupt_id
    ));

    let not_rendered = seed_governed_network_interrupt(&ctx.db, session_id).await;
    let error = dispatch::handle_serialized_request(
        Request::ResolveInterrupt {
            interrupt_id: not_rendered,
            response: proto::ResolveResponse::Cancel,
        },
        &mut state,
        &shared,
        &ctx,
        &mut effects,
    )
    .await
    .expect_err("a different non-rendered governed interrupt is denied");
    assert_eq!(error.code, ErrorCode::Authorization);

    let old_rendered = state.attached.as_ref().unwrap().rendered_interrupts.clone();
    state.attached.as_mut().unwrap()._interactive_guard = None;
    state.attached.as_mut().unwrap()._interactive_guard =
        Some(handle.register_interactive_client());
    state.attached.as_mut().unwrap().rendered_interrupts = Arc::new(StdMutex::new(HashSet::new()));
    assert!(crate::sync::lock_or_recover(&old_rendered).contains(&interrupt_id));
    let recycled_error = dispatch::handle_serialized_request(
        Request::ResolveInterrupt {
            interrupt_id,
            response: proto::ResolveResponse::Cancel,
        },
        &mut state,
        &shared,
        &ctx,
        &mut effects,
    )
    .await
    .expect_err("a replacement attachment cannot reuse the old render identity");
    assert_eq!(recycled_error.code, ErrorCode::Authorization);
    assert!(work_rx.try_recv().is_err());
}
